window.CONF={"days": [{"id": "d1", "date": "11/14（六）", "short": "11/14", "video": "a68KpkrjF9A", "theme": "以社區醫療為基礎的整合照顧／醫療與社區服務協作", "sessions": [{"id": "1-0", "slot": "09:00–09:30", "title": "開幕式：貴賓致詞、大合照", "role": "", "speaker": "", "org": "", "orgType": "主辦單位", "t": 690, "summary": "第六屆台灣社區整合照顧研討會開幕。總盟陳節如理事長回顧自2014年引進日本在宅醫療經驗、倡議社區型急性後期照護的歷程，強調以人為本、以社區為基礎、以家庭為中心。王正旭委員盤點2024–2026年長照與醫養結合的進展及人力、財源、社區共生三大挑戰；陳時中政委提醒醫照整合要跨越部門介面、把成功計畫納入制度；石崇良部長宣示長照3.0、健康幣等新政，並提出預防、去中心化、整合、科技四大政策方向。", "points": [{"t": 791, "kind": "策略", "tags": ["日本經驗", "居家醫療"], "text": "陳節如理事長：總盟自2014年看見民眾在醫療與照顧之間的困境，參考日本在宅醫療經驗引進居家醫療，並持續學習澳洲、美國、日本的整合照顧經驗，目標是讓民眾不必因缺乏社區支援而離開熟悉的環境。"}, {"t": 875, "kind": "政策", "tags": ["急性後期照護", "復健病房"], "text": "陳理事長：去年研討會倡議建立社區為基礎的急性後期照顧，衛福部今年7月即啟動相關試辦（復健病房），明年度可望再增加參與醫院；本屆四大主題為社區醫療整合照顧、醫療與社區協作、復健病房試辦經驗、醫療照顧需求重症兒童。"}, {"t": 997, "kind": "建議", "tags": ["醫照整合", "健康台灣"], "text": "陳理事長：健康台灣的最終目標是醫照合一，但長照與醫療的結合仍有許多細節待解；總盟扮演監督角色，主張以人為本、以社區為基礎、價值導向、以家庭為中心，用台灣的能力與經費發展台灣模式。"}, {"t": 1324, "kind": "政策", "tags": ["長照3.0", "出院準備"], "text": "王正旭委員盤點2024–2026進展：長照從失能後照顧轉向源頭預防（導入ICOPE評估、深化ABC據點），醫養結合與出院準備銜接深耕、醫療與長照資訊對接，出院準備的等待時間大幅縮短。"}, {"t": 1384, "kind": "政策", "tags": ["長照3.0", "家庭照顧者"], "text": "王委員：2025年9月起放寬聘僱外籍看護工的家庭也能使用社區照顧服務；交通與營養給付的額度與次數擴大；智慧照顧與輔具改採租賃；小規模多機能服務中心床數由9床擴充到18床。"}, {"t": 1482, "kind": "挑戰", "tags": ["人力培育", "財源與預算"], "text": "王委員點出未來三大挑戰：照顧人力的續航與培力、財政永續平衡（立法院正審預算），以及結合地方創生、志工網絡、社會處方與民間企業，落實社區共生生態系。"}, {"t": 1710, "kind": "建議", "tags": ["醫照整合", "跨部會協作"], "text": "陳時中政委：預防、醫療與長照應是一條路而非切成幾段；各行政單位專業很強，但一跨出所屬就難整合，雙方都要退一步為整個社會著想；下一步除醫照整合，更要把成功的試辦計畫整合進制度面。"}, {"t": 1954, "kind": "數據", "tags": ["長照3.0", "財源與預算"], "text": "石崇良部長：台灣去年已進入超高齡社會，65歲以上人口約476萬；健保預算已超過1兆元，長照預算超過1,100億元。"}, {"t": 1986, "kind": "政策", "tags": ["長照3.0", "失智照護"], "text": "石部長：今年開始實施長照3.0，發布失智症3.0行動綱領，並啟動為期兩年、地毯式的獨居長者社區關懷訪視計畫；10月1日啟動「健康幣」，以民眾自發參與帶動行為與習慣改變。"}, {"t": 2073, "kind": "政策", "tags": ["健康台灣", "數位科技"], "text": "石部長提出四大政策方向：一、往前端預防與健康促進；二、去中心化，回到以家、以社區為主的照護；三、整合醫照、資訊與財務服務；四、導入科技，今年起長照給付納入科技輔具，以因應少子化帶來的人力短缺。"}]}, {"id": "1-1", "slot": "09:30–10:20", "title": "專題演講：以社區醫療為基礎的整合照顧落實的現況與展望", "role": "主講", "speaker": "石崇良 部長", "org": "衛生福利部", "orgType": "政府機關", "host": "台灣社會福利總盟 陳節如理事長", "t": 2400, "summary": "石崇良部長從超高齡、慢性病與癌症雙重負擔、人力短缺、資安與藥物韌性等挑戰切入，說明健康台灣以延長餘命、降低不健康餘命為總目標。政策兩大主軸：一是往前推到預防與健康促進，包括預防保健年齡下修、大家醫2.0、代謝症候群計畫、健康幣與ICOPE、社會處方；二是讓照護從醫院回到家庭社區，包括衛福部組改、長照3.0藍圖、資訊整合、出院準備零等待、在宅急症、復健病房、共生宅試辦、獨老訪視與ACP推廣。", "points": [{"t": 2581, "kind": "數據", "tags": ["健康台灣"], "text": "國人平均餘命已超過80歲，活過65歲者平均還有約20年（約到85歲）；但健康餘命比平均餘命少約8年，目標是從高齡長壽走向健康長壽。"}, {"t": 2740, "kind": "挑戰", "tags": ["財源與預算", "健康台灣"], "text": "全球醫護人力到2030年預估短缺約1,100萬人；台灣更嚴峻，2061年起65歲以上人口將超過15–64歲工作人口，轉為倒金字塔。部長以此對「65歲以上免繳健保費」提案表示憂心，強調唯有延長健康時間，讓上層負荷變輕、下層更有能力，健保才能永續。"}, {"t": 2959, "kind": "數據", "tags": ["健康台灣"], "text": "兩大健康負擔：以三高為主的慢性病占十大死因7項，高齡者約85%至少有一種，影響餘命約3.8歲；癌症蟬聯十大死因之首44年，影響餘命約13.7歲。兩者都可透過公共衛生介入預防。"}, {"t": 3037, "kind": "政策", "tags": ["健康台灣"], "text": "健康台灣具體目標：慢性病推動「888」控制目標，癌症與慢性病死亡率在2030年前下降三分之一；總目標是平均餘命延長3歲（79歲到82歲），並降低不健康餘命比例，部長認為餘命目標有機會達成。"}, {"t": 3150, "kind": "政策", "tags": ["財源與預算", "健康台灣"], "text": "策略一：擴大健康投資。近年健保與公務預算（含各項預防保健）投入為史上最多，但重點是用預算推動照護轉型，從住院轉向門診與居家照顧。"}, {"t": 3208, "kind": "政策", "tags": ["人力培育", "數位科技"], "text": "策略二：重塑人力架構。不需要人做的交給科技，不需高度專業的工作重新分配、經訓練由他人承擔，把高度專業留給專業人員；同時加強育才、留才、培才，縮小學用落差，改善治理制度與工作流程。"}, {"t": 3283, "kind": "挑戰", "tags": ["數位科技"], "text": "策略三、四：數位加速的同時要強化資訊韌性與資安治理，長照管理系統改以自然人憑證或健保卡登入即是一例（部長坦言準備期需再調整）；另要建立藥物韌性，台灣藥物多仰賴進口，在全球供應鏈去全球化、美國藥品關稅壓力下相對薄弱。"}, {"t": 3506, "kind": "政策", "tags": ["健康台灣", "健保給付"], "text": "健康台灣架構：2024年總統主持健康台灣論壇揭示七大願景，邱泰源前部長推出第一期計畫；推動架構為強化健康促進、改變服務模式、調整支付制度，並以藥物韌性與數位韌性為基礎。"}, {"t": 3626, "kind": "政策", "tags": ["健康台灣", "社區醫療"], "text": "成人預防保健去年起下修年齡，提早篩檢後發現不少人已有三高或代謝症候群。健康者在社區持續推動衛教與健康識能；已有代謝症候群或慢性病者導入健康照護體系。"}, {"t": 3736, "kind": "政策", "tags": ["社區醫療", "健保給付"], "text": "大家醫計畫整合：由家庭醫師提供全人照顧，把疫苗、篩檢等預防保健納入；並把糖尿病共照、CKD、DKD等疾病導向的P4P計畫整併進大家醫計畫，讓三高與慢性腎病病人都進入照護網，去年起推動。"}, {"t": 3852, "kind": "數據", "tags": ["健康台灣", "就學與教育"], "text": "40歲以下提早篩檢的最大問題是肥胖，部長稱台灣是亞洲最胖的國家之一；高三學生過重比例已超過30%。未滿40歲已見血脂、血壓、血糖異常，兒童與青壯年健康是國家未來的關鍵。"}, {"t": 4048, "kind": "數據", "tags": ["健康台灣", "社區醫療"], "text": "代謝症候群計畫以衛教與生活型態改變介入，約兩成個案可逆轉、不需長期用藥，多數人的體重、腰圍與各項指標獲得改善。"}, {"t": 4083, "kind": "政策", "tags": ["健保給付", "數位科技"], "text": "大家醫2.0：把過去分散的計畫整合為糖、心、腎共同管理的整合性慢性病管理，同時納入預防保健、採成果導向支付、導入數位照顧。"}, {"t": 4159, "kind": "政策", "tags": ["健康台灣", "社區醫療"], "text": "全年齡健康促進：調查顯示營養失衡、從青少年到長者活動量都不足。國健署推動健康職場；高齡者透過銀髮健身俱樂部、社區關懷據點、社區營養推廣中心導入健康促進。"}, {"t": 4231, "kind": "政策", "tags": ["健康台灣", "數位科技"], "text": "健康幣以行為誘因機制結合個人化健康資料驅動改變。第一階段為預防保健類（篩檢、疫苗、生活型態評估量表，填量表給100點），高齡者COVID疫苗接種增加約30%，已加購疫苗；已有約80萬人填量表，12月將公布國人六大生活型態分析結果。"}, {"t": 4341, "kind": "政策", "tags": ["健康台灣", "數位科技"], "text": "健康幣下一步納入ICOPE：鼓勵65歲以上長者每年完成六項功能評估，讓社區掌握介入方向；並與運動部合作納入運動紀錄，整合自費健檢與勞工健檢資料，建立個人健康行為軌跡。"}, {"t": 4380, "kind": "政策", "tags": ["社區醫療", "數位科技"], "text": "在個人健康資料基礎上導入社會處方，涵蓋活動、營養、心理與數位處方，不只是慢性病管理；同時要縮小數位落差，避免數位推動造成新的健康不平等。"}, {"t": 4458, "kind": "政策", "tags": ["醫照整合", "居家醫療"], "text": "照護整合第二主軸：從醫院照護轉為家庭與社區照護，發展居家醫療、在宅急症、復能與長照在地支援，把過去醫療、長照、社福各自運作的分段式照顧，整合為全人全程的連續照顧。"}, {"t": 4496, "kind": "政策", "tags": ["跨部會協作", "長照3.0"], "text": "組織整合先行：長照業務過去分屬長照司、護理及健康照護司、社家署三套系統。組改已完成立法，預計明年上半年完成，成立新署（部長簡稱「社照署」），把長照、老人福利與身障服務放在同一部門，盤點整合資源；健保署與國健署分責健保與前端預防。"}, {"t": 4578, "kind": "政策", "tags": ["長照3.0", "醫照整合"], "text": "長照3.0服務藍圖以社區為基礎、醫照整合，追求服務最佳化與在地安老，分三塊：社區預防強化（維持健康越久越好）、醫療與長照無縫銜接（急性病後積極復能）、在宅與機構照顧最佳化（讓失能者留在社區、減少移動）。"}, {"t": 4740, "kind": "政策", "tags": ["數位科技", "醫照整合"], "text": "資訊整合是醫照整合的關鍵：要串接長照資料、健保居家醫療資料、機構照護資料與公衛資料。先從在宅醫療資訊照護平台介接，長照服務資料與大家醫平台已各自整合，再做比對交換，並推動以FHIR為標準的資料標準化。"}, {"t": 4810, "kind": "政策", "tags": ["出院準備", "長照3.0"], "text": "出院準備銜接長照：今年改為醫院自行媒合或由A單位媒合兩種方式，主張「住院就是出院準備的開始」；出院後等待長照服務的時間去年為4天，今年目標2天，朝0天努力。"}, {"t": 4851, "kind": "政策", "tags": ["在宅急症照護", "健保給付"], "text": "在宅急症照護今年已調整支付，包括醫檢師、醫放師、藥事服務與護理費；成效良好，照護天數比傳統住院短，最後仍需送醫院的不到約4%。另發現部分在宅急症個案未獲長照服務，正加強兩者銜接。"}, {"t": 4927, "kind": "政策", "tags": ["住宿式機構", "在宅急症照護"], "text": "住宿式機構減少就醫計畫讓住民在機構內就得到急症照護、不必常送醫院；部長認為目前覆蓋率還不夠高，未來要媒合更多機構參與。"}, {"t": 4962, "kind": "政策", "tags": ["復健病房", "急性後期照護"], "text": "復健病房仍在試辦摸索，最終希望PAC都能轉型為此模式：院內有「仿家」設計，在復能過程中做好回家準備，讓更多病人回歸社區獨立生活，而非轉入長照機構；先從腦中風開始評估成效再調整，署長稱之為「復健補習班」。下一步也要思考社區式復能：社區據點目前做預防衰弱，能否進一步提供復健（陳節如理事長常提出的建議）。"}, {"t": 5111, "kind": "挑戰", "tags": ["居家醫療", "家庭照顧者"], "text": "少子化下居家醫療的前提是家中有人，但獨老、雙老家庭缺乏照顧者，居家醫療難以進入，一對一服務成本極高，需要住宿式機構、小規模多機能以外的一對多模式。"}, {"t": 5183, "kind": "政策", "tags": ["長照3.0", "偏鄉"], "text": "共生宅試辦：參考日本「母親之家」（かあさんの家）模式，今年下半年先在長照資源不足地區示範，以「沒有血緣的家人」仿家方式，收CMS 4級以上且有居家醫療或安寧需求、或失智CDR 2分以上有行為症狀者，整合健保與長照費用，並結合社區志工人力。"}, {"t": 5262, "kind": "政策", "tags": ["家庭照顧者", "數位科技"], "text": "獨居長者關懷訪視由行政院特別預算支持，兩年62.5億元，目前已完成約25%、七十多萬人；風險分級二級以上可安裝緊急救援裝置，安裝率約30–50%。訪視資料將與健保串接，有就醫事件即重新評估，並導入AI做智慧照顧。"}, {"t": 5378, "kind": "政策", "tags": ["安寧緩和", "健保給付"], "text": "安寧與ACP：簽署AD也將給健康幣。ACP已有健保給付、門診可做，但簽署人數仍少；立法院正審議修法（劉建國委員等提案），擬放寬ACP可由醫療機構以外的機構提供，尚未通過，民間團體可開始規劃培訓。"}, {"t": 5494, "kind": "政策", "tags": ["社區醫療", "偏鄉"], "text": "多元社會處方要與ACP、AD結合，並納入偏鄉資源平權；部長肯定北市聯醫推動的社會處方，但指出那是都會模式，偏鄉與文健站如何推動是下一步。總結健康台灣三目標：健康老化、在地安老、安寧善終。"}]}, {"id": "1-2", "slot": "10:20–11:20", "title": "社區整合照護藍圖", "role": "與談", "speaker": "黃勝堅 前總院長", "org": "臺北市立聯合醫院", "orgType": "醫院", "handout": "https://drive.google.com/file/d/1hg_z2KJcids7I9chnPwUKluCo0ZnHd2U/view", "t": 5577, "summary": "黃勝堅前總院長從實務指出，台灣醫療與長照各站服務都好，問題在站與站之間的斷點：病人走不進診所後家庭醫師就消失、出院準備流於形式、居家醫療越做越萎縮、末期病人在醫院間漂流。他主張社區照護要從「提供服務」走向「共同承擔責任」，建議由居家護理所擔任串接醫療與長照的引路人並給予溝通給付、每次住院出院都當成整合契機、給予PCOC正式給付，並以區域共同責任模式與健康台灣深耕計畫作為改革實驗場域。結論：沒有共同支付就沒有共同責任，就沒有整合照顧。", "points": [{"t": 5641, "kind": "建議", "tags": ["醫照整合"], "text": "核心主張：未來社區照護應從「提供服務」轉為「大家共同承擔責任」，中間有許多斷點需要逐步彌補。"}, {"t": 5696, "kind": "挑戰", "tags": ["醫照整合", "人力培育"], "text": "增加的不只是老人，而是同時需要醫療與生活照顧的老人；照顧對象除了病人，還要顧到照顧者與醫療團隊本身（醫療團隊 burn out、人力不足）。"}, {"t": 5734, "kind": "數據", "tags": ["長照3.0"], "text": "2035 年失能人口預估由約 92 萬增至約 130 萬；吞嚥、營養、反覆住院等問題不是醫院以疾病為導向就能解決。"}, {"t": 5822, "kind": "挑戰", "tags": ["醫照整合"], "text": "台灣醫療與長照每一站服務都很好，問題是民眾「有問題時找不到誰來照顧」，站與站之間的斷點沒有連起來；需要有人畫出醫療＋長照的「交通路線圖」，並有引路人帶路。"}, {"t": 5904, "kind": "數據", "tags": ["社區醫療", "居家醫療"], "text": "目前約 40% 家庭有家庭醫師，但病人一旦走不進診所，家庭醫師的照顧往往就斷了；應真正賦予社區醫療群照護責任，並有人負責串接資源。"}, {"t": 5984, "kind": "策略", "tags": ["出院準備", "安寧緩和"], "text": "高齡者病況變化多半可預期，每次住院都應有人主動告知家屬病程走向（例如一年住院三次可能進入末期），並討論是否啟動居家醫療。"}, {"t": 6059, "kind": "挑戰", "tags": ["出院準備"], "text": "台灣自民國 83 年就有出院準備，歷史比居家醫療還久，但以醫院目前負荷很難做好；醫師不太願意做、全推給出院準備護理師，資料內容品質也不夠，是斷點反覆出現的原因。"}, {"t": 6138, "kind": "挑戰", "tags": ["居家醫療", "社區醫療"], "text": "病人無法到院後常變成家人代為拿藥，慢性處方箋可能三年沒調整，健保有付錢但病人沒得到真正需要的照顧。"}, {"t": 6212, "kind": "挑戰", "tags": ["居家醫療", "健保給付"], "text": "居家醫療投入者不多，不是醫師不願或不會，而是制度沒有支持；他將居家醫療分為 S1（醫師單獨前往）、S2（以護理師為主角、主治醫師常更換）、S3（居家安寧）等不同型態，各有運作難處。"}, {"t": 6341, "kind": "挑戰", "tags": ["居家醫療"], "text": "他任聯合醫院總院長時是居家醫療最旺盛的時期，但十多年後反而越來越萎縮，醫師認為花的時間太多、不划算；結果常是家屬自己變成個管師。"}, {"t": 6398, "kind": "數據", "tags": ["居家醫療", "長照3.0"], "text": "引用較早資料：長照 CMS 第 7 級者約 89%、第 8 級者約 70% 沒有使用居家醫療，這些人的醫療多半仍是到醫院拿藥。"}, {"t": 6440, "kind": "挑戰", "tags": ["社區醫療"], "text": "政府目標 2035 年責任醫師（家庭醫師）涵蓋率達 70%，但屆時失能者是否真能被家庭醫師照顧到，仍是很大的問號。"}, {"t": 6604, "kind": "策略", "tags": ["醫照整合", "數位科技"], "text": "臺北市立聯合醫院做法：把每個家庭的照顧相關人員（里長、里幹事、照服員、送餐人員、居家護理師等）拉進同一個 LINE 群組，有問題就丟出來；實際上最常回應的是居家護理師。"}, {"t": 6686, "kind": "建議", "tags": ["出院準備", "醫照整合"], "text": "應賦予大醫院責任：每次住院、每次出院都是整合的契機，要坦白與病人家屬談病程與後續選擇，而不只是把出院準備接到長照。"}, {"t": 6747, "kind": "建議", "tags": ["人力培育", "出院準備"], "text": "肯定出院準備銜接長照的天數已大幅縮短，但光接長照不夠，應發展跨體系銜接的轉銜照護專業；台灣這方面人才太少、給付與醫院計酬也不明確，建議趕快培育人才。"}, {"t": 6871, "kind": "建議", "tags": ["醫照整合", "居家醫療"], "text": "大膽建議賦予居家護理所擔任醫照整合的串接者；已有居家護理所與醫院門診醫師合作的案例：門診醫師開醫囑、居家護理師執行，能力不足時再找合作的居家醫療醫師。"}, {"t": 6947, "kind": "策略", "tags": ["急性後期照護"], "text": "出院轉銜是否成功，看 30 天後病人在哪裡；導入周全性老年評估（CGA）可降低再入院比率。"}, {"t": 6986, "kind": "建議", "tags": ["急性後期照護"], "text": "現行 PAC 品質很好但收案人數很少，建議將 PAC 從「病況穩定、積極復健」擴大到周全性老人照顧；可先在醫學中心示範，再以區域方式建立共同承接。"}, {"t": 7059, "kind": "策略", "tags": ["居家醫療", "安寧緩和"], "text": "以吞嚥為例：病人帶鼻胃管回家後，是否能移除、改用其他方式，或趁長輩還能做決定時導入 ACP／AD（例如不要人工營養），都需要回到家後反覆評估與多次溝通，很難在醫院內完成。"}, {"t": 7134, "kind": "建議", "tags": ["健保給付", "醫照整合"], "text": "再次建議由居家護理師擔任醫療與長照邊界的引路人，並對居中穿針引線的溝通工作給予合理給付；溝通已被承認是醫療的一部分。"}, {"t": 7287, "kind": "建議", "tags": ["安寧緩和", "住宿式機構"], "text": "要終結末期病人在各醫院間「漂流」；對無法在家善終者，可考慮共生宅等形式為他們找到最後的家。"}, {"t": 7287, "kind": "建議", "tags": ["安寧緩和", "健保給付"], "text": "建議給予 PCOC（緩和照護門診）正式給付，開設「第四模式」：目前安寧門診一位病人看 30–40 分鐘，給付卻與一般門診相同；PCOC 不是簽 AD 的地方，而是社區居家醫療與居家護理所的後援窗口。"}, {"t": 7361, "kind": "建議", "tags": ["醫照整合", "財源與預算"], "text": "提出「區域共同責任模式」（Regional Accountable Care Model）：沒有共同支付就沒有共同責任，沒有共同責任就沒有整合照顧。"}, {"t": 7361, "kind": "策略", "tags": ["跨部會協作", "偏鄉"], "text": "金山模式可參考：他在金山三年整合社政、衛政、民政與 NPO 力量，人口雖不多但是成功案例。"}, {"t": 7397, "kind": "建議", "tags": ["健康台灣", "跨部會協作"], "text": "建議以健康台灣深耕計畫作為體系改革的實驗場域，避免各自為政、只留下一堆折舊設備，也避免「用第十一個計畫去串聯前十個計畫」；病人不在乎是哪個計畫，只在乎有沒有人把他照顧好。"}]}, {"id": "1-3", "slot": "10:20–11:20", "title": "從居家醫療到社區整合照顧", "role": "與談", "speaker": "林宏榮 院長", "org": "奇美醫院", "orgType": "醫院", "handout": "https://drive.google.com/file/d/1fl6D3h_b2LgwMdoW2rPPXo8hjnQc1Tx0/view", "t": 7478, "summary": "林宏榮院長分享奇美「不做長照，但用醫療支援長照」的路線。他從急診壅塞談起，引介美國急性非預期照護模式（AUCM），主張急診以遠距、居家醫療與轉銜照護減少不必要住院。奇美以約2000名居家醫療個案為基礎，2023年啟動在宅急症照護，引進居家X光與24小時輸注抗生素，再推OPAT，平均減少住院3.4天、社會投資報酬率逾8倍。並以赴日參訪培養年輕醫師；佳里奇美腦中風居家PAC的死亡與再入院率遠低於全國，成本約住院模式三分之一。", "points": [{"t": 7510, "kind": "策略", "tags": ["醫照整合"], "text": "奇美的定位：「我們不做長照，但用醫療資源支援長照，讓長照做好」；醫療必須先進入社區、進入長照，才談得上整合。"}, {"t": 7655, "kind": "挑戰", "tags": ["在宅急症照護"], "text": "急診壅塞是長照與社區病人返回醫院的入口堵塞：多重共病、反覆進出的高齡病人塞在急診住不進病房，醫學中心每天都有數十位。"}, {"t": 7811, "kind": "建議", "tags": ["在宅急症照護"], "text": "急診醫學會去年提出的建議中有一項特別的「推動急診住院的替代選項」：病人不一定要住院，但必須有去處與治療方式。"}, {"t": 7841, "kind": "策略", "tags": ["在宅急症照護", "數位科技"], "text": "參考美國急診醫學會爭取的「急性非預期照護模式」（AUCM）：讓急診跨出四面牆，爭取三項工具——病情不確定者先回家以遠距醫療追蹤、急診醫師延伸提供居家醫療、配置轉銜照護人員（TCN）。"}, {"t": 8082, "kind": "建議", "tags": ["健保給付", "在宅急症照護"], "text": "AUCM 是價值醫療模式：急診醫師從「指揮交通」變成醫療資源整合者，照顧病人一段時間，並依病人結果而非看診量計酬，需有對應給付。"}, {"t": 8268, "kind": "數據", "tags": ["居家醫療"], "text": "奇美在黃勝堅前總院長啟蒙下長期投入居家醫療，一家醫院在案管理個案約 2000 人，被稱為全台規模最大的居家醫療團隊之一。"}, {"t": 8268, "kind": "政策", "tags": ["在宅急症照護"], "text": "奇美於 2023 年啟動在宅急症照護；醫學中心只能做 C 模式（居家），機構住民的 B 模式由佳里奇美醫院努力推動中。"}, {"t": 8301, "kind": "策略", "tags": ["在宅急症照護", "數位科技"], "text": "為讓在宅住院可行，奇美與台灣 ICT 廠商合作，引進全台第一台在宅胸部 X 光機（約 3 公斤），2024 年拍下全台第一張居家胸部 X 光；也提供超音波、心電圖、生化檢驗等居家設備。"}, {"t": 8338, "kind": "政策", "tags": ["在宅急症照護", "健保給付"], "text": "引進 24 小時連續輸注抗生素（infusor），讓居家可使用一線抗生素，並很快獲納入健保給付範圍。"}, {"t": 8366, "kind": "數據", "tags": ["在宅急症照護"], "text": "在宅急症照護收案已近 700 例（講義寫 600+），多數來自急診與門診，為全國醫院中收案最多者之一。"}, {"t": 8397, "kind": "政策", "tags": ["在宅急症照護", "健保給付"], "text": "從向部長建議在宅住院到健保上線約一年，上線時由賴總統主持第一例；之後與感染症醫學會建議 OPAT（門診靜脈抗生素治療），三個月即上線，以紓解急診壅塞。"}, {"t": 8463, "kind": "策略", "tags": ["在宅急症照護", "急性後期照護"], "text": "奇美提供「全盤解決方案」：急診病人可回家觀察、符合條件的感染症以在宅住院治療、行動力佳者到門診接受 OPAT；已住院者病情穩定後可提早出院改接在宅住院或 OPAT，讓住院精實化，並減少臥床失能、譫妄與跌倒。"}, {"t": 8527, "kind": "數據", "tags": ["在宅急症照護"], "text": "每位病人平均減少住院約 3.4 天；講義另列 OPAT 已逾 800 案、每月約 30–40 案。奇美研究登上 SCI 期刊，證實在宅住院比傳統住院減少約 1/3 住院天數、2/3 醫療費用，回急診與再住院率無差異（講義）。"}, {"t": 8560, "kind": "策略", "tags": ["在宅急症照護", "人力培育"], "text": "因 24 小時輸注器等技術有門檻，奇美在全台巡迴教學推廣；台大、北榮、中榮、長庚體系、部立醫院等超過 40 家醫院曾來參訪。"}, {"t": 8595, "kind": "策略", "tags": ["日本經驗", "在宅急症照護"], "text": "日本在宅醫療代表人物佐佐木淳公開引用奇美研究，並向日本政府建議導入台灣在宅住院經驗；新加坡也派醫師與護理長來奇美學習。"}, {"t": 8655, "kind": "數據", "tags": ["在宅急症照護", "財源與預算"], "text": "奇美與顧問公司計算在宅急症照護的社會投資報酬率（SROI）超過 8 倍，即健保每投入 1 元，社會可獲約 8 元效益；病人與家屬免於往返與請假，也較節能。"}, {"t": 8756, "kind": "政策", "tags": ["長照3.0", "居家醫療"], "text": "長照 3.0 重點是打造居家、社區、機構、醫療、社福一體式服務；總統表示居家醫療就是長照 3.0 醫療與長照整合的起點。"}, {"t": 8826, "kind": "策略", "tags": ["日本經驗", "人力培育"], "text": "自 2018 年起每年派一兩團赴日，看長照機構、居家醫療、回復期病房、跨領域出院支援、在宅急症值班、共生宅與安寧診所，也帶董事會同行；之後也赴澳洲、新加坡交流。"}, {"t": 9045, "kind": "策略", "tags": ["人力培育"], "text": "每年派十幾人、以年輕醫師為主赴日；年輕醫師原以為居家醫療是被指派的苦差事，看到日本醫師做得愉快後便能接受，成為長期培養人才的關鍵。"}, {"t": 9105, "kind": "建議", "tags": ["社區醫療", "日本經驗"], "text": "日本 2040 年方向為地域醫療整合進化、人才確保、數位轉型；台灣缺的是「社區醫療資源醫院」，應由醫院擔任後援，讓社區醫院轉型為居家醫療與社區醫療的資源基地。"}, {"t": 9166, "kind": "策略", "tags": ["急性後期照護", "復健病房"], "text": "2019 年起做腦中風居家 PAC：因轉住院型 PAC 太困難，改由治療師到家中，用彈力帶與家中設施訓練，並教家人協助；由佳里奇美承接永康奇美的病人，收案量為全國第一。"}, {"t": 9255, "kind": "策略", "tags": ["急性後期照護", "家庭照顧者"], "text": "居家 PAC 採「許願式服務」：依個案想達成的活動訂定個別化訓練，依家中環境設計輔具與無障礙改善，並讓家人參與以強化照顧者功能。"}, {"t": 9286, "kind": "數據", "tags": ["急性後期照護"], "text": "佳里奇美居家 PAC 品質指標（114 年 1–6 月）：一年內死亡率 0.8%（全國 7.36%）、14 日內再入院率 4.3%（全國 9.69%）、30 日內再入院率 4.3%（全國 14.63%）。"}, {"t": 9320, "kind": "數據", "tags": ["急性後期照護"], "text": "結案後仍需門診復健的比率：全國約 59%，佳里奇美居家 PAC 約 22%，多數轉為居家自行復健。"}, {"t": 9349, "kind": "數據", "tags": ["急性後期照護", "健保給付"], "text": "日常生活功能（BI）每進步一分所需給付：居家模式約 1445 點、住院模式約 4574 點，成本約只有三分之一，照護成效相近甚至更好。"}]}, {"id": "1-4", "slot": "11:20–12:00", "title": "上午綜合座談", "role": "座談", "speaker": "", "org": "", "orgType": "", "t": 9468, "summary": "上午綜合座談由陳節如理事長主持，石崇良部長、黃勝堅前總院長、林宏榮院長回應。提問集中在：居家護理所擔任整合引路人能否試辦、老衰PAC條件太窄、居家復健難落地、居家移除鼻胃管與導尿管無給付、居家安寧人次上限、一案多管，以及奇美如何留住居家醫療人才。石部長表示將以風險分級加個案管理、總包式財務誘因推動全人照護，優先強化住宿式機構醫照整合並檢討PAC；健保總額三年增近2000億，未來給付須走價值導向，居家醫療要走向有基地醫院支援的團隊。", "points": [{"t": 9726, "kind": "建議", "tags": ["醫照整合", "居家醫療"], "text": "台灣居家護理暨服務聯盟總會名譽理事長提問：能否選定縣市試辦，讓居家護理所擔任社區整合的媒介角色，銜接高齡照顧與長照。"}, {"t": 9853, "kind": "挑戰", "tags": ["急性後期照護", "失智照護"], "text": "林口長庚高齡醫學科陳醫師反映：衰弱高齡（老衰）PAC 收案條件只有四項，失智等多重疾病個案難以納入，轉介轉銜挫折很多，盼放寬。"}, {"t": 9938, "kind": "建議", "tags": ["人力培育", "日本經驗"], "text": "一位在日本從事社區照顧整合培訓近 17 年的與會者提醒：老人不等於病人，應以自立生活為目標；台灣缺乏像日本 Care Manager 的角色，建議培養社工、營養師、藥師與照服員等作為社區銜接的關鍵人物，並提升照服員的半專業能力，避免把所有工作壓在護理師身上。"}, {"t": 10137, "kind": "策略", "tags": ["醫照整合", "居家醫療"], "text": "黃勝堅前總院長回應：建議由居家護理所護理師擔任穿針引線者，是因為他們已深入社區與家庭，應急最快；長遠而言，任何經過培訓、願意做的專業人員都可以，醫師能做更好但量能不足。"}, {"t": 10260, "kind": "政策", "tags": ["醫照整合", "健康台灣"], "text": "石部長回應：方向是分級照顧，健康與亞健康者強化自我照顧，高風險者導入個案管理；過去最成功的 care management 是糖尿病共同照護，現在需要的是跨資源的銜接。"}, {"t": 10358, "kind": "政策", "tags": ["偏鄉", "醫照整合"], "text": "石部長：花東正推動「全人全社區照護」，先做健康風險分級、導入個案管理再連結資源；溝通成本難以按分或按次計費，改用總包式給付，事情相對單純。"}, {"t": 10486, "kind": "政策", "tags": ["住宿式機構", "醫照整合"], "text": "石部長：目前最脆弱的是住宿式長照機構，健保多只做巡診；長照已將補助提高到每月 1 萬 5 千元，接下來要以財務誘因把醫照整合與個案管理導入住宿式機構。"}, {"t": 10563, "kind": "政策", "tags": ["急性後期照護", "復健病房"], "text": "石部長：推復健病房時發現現行 PAC 並不成功，將檢討 PAC 計畫，避免與復健病房對象重疊、再用另一個計畫來整合；細節請健保署帶回並於隔天場次再討論。"}, {"t": 10636, "kind": "挑戰", "tags": ["急性後期照護", "社區醫療"], "text": "池上好診所鍾泓翊主任提問：居家 PAC 成效好，但病人從醫院返家後，社區端實際上難以執行居家復健，問題在處方釋出、醫師銜接，還是治療師如何配合？"}, {"t": 10747, "kind": "策略", "tags": ["居家醫療", "醫照整合"], "text": "台灣居家醫療相關學會理事長分享苗栗經驗：S1 居家醫療只有醫師一人，因此每次出訪都安排 A 個管或社工同行，及早連結後端長照資源（老老照顧、獨居等）。他也指出在宅急症照護的臨終安寧包裹式給付條件與獎勵仍模糊，盼及早明確。"}, {"t": 10965, "kind": "挑戰", "tags": ["醫照整合"], "text": "聖馬爾定醫院精神部行政主任、中華聖母基金會執行長黎世宏指出台灣最大問題是「一案多管」：醫療、長照、社福各管各的；日本社區整合的個管員一人最多 40 多案，並整合醫療與照顧。"}, {"t": 11065, "kind": "挑戰", "tags": ["人力培育", "健保給付"], "text": "黎世宏請教林院長：在給付點值不成比例下，奇美如何留人，讓在宅急症照護與居家 PAC 都做到數百例規模。"}, {"t": 11136, "kind": "建議", "tags": ["健保給付", "居家醫療"], "text": "居家醫療學會理事（耳鼻喉科醫師）建議：目前只有醫院移除鼻胃管有給付，居家醫師到家或機構移除沒有給付，居家護理師也只能更換不能移除；開放給付可減少醫療支出並提升生活品質。"}, {"t": 11287, "kind": "建議", "tags": ["居家醫療", "數位科技"], "text": "新北雙溪、貢寮一帶的居家護理所護理師建議：仿日本讓醫院與居家護理所人員互相實習；遠距生理監測等 AI 技術若由護理師執行應可直接申請；活用護理師開設的家庭托顧；用預測失能量表篩出高風險長輩及早介入；並研議專科護理師在社區可執行的處置範圍以補醫師不足。"}, {"t": 11533, "kind": "建議", "tags": ["住宿式機構", "跨部會協作"], "text": "中華民國自閉症權益促進會理事長提問：林口世大運選手村社會住宅的自閉症者居住專案已推動七年、成果良好，盼依社會福利基本法納入社宅持續推動，而非僅以專案方式。"}, {"t": 11619, "kind": "建議", "tags": ["安寧緩和", "急性後期照護"], "text": "在宅醫療學會副理事長黎家銘提出三點：居家安寧每月人次上限（約 45 人次）應鬆綁並給予合理報酬；擴大居家 PAC，建立醫院與居家團隊互相轉介的平台；居家移除導尿管、指導間歇導尿應有合理給付。"}, {"t": 11798, "kind": "策略", "tags": ["人力培育", "居家醫療"], "text": "林宏榮院長回應留人之道：帶年輕醫師赴日參訪，並讓醫師照顧自己出院的病人以延續照護（如神經科、神經外科）；全院有 40 多位、十幾科醫師在跑居家醫療。給醫師的分潤不必特別高（約健保給付的七到八成），關鍵是要有量；有內科醫師專做居家醫療不看門診也過得很好。"}, {"t": 11885, "kind": "政策", "tags": ["居家醫療", "社區醫療"], "text": "石部長：居家醫療給付會朝足夠的方向努力，但更重要的是讓基層從獨立診所走向團隊，像日本一樣多家診所與各類醫事人員輪流值班出診，後面再有資源醫院（基地醫院）作為 hub 支援檢查與短期住院。"}, {"t": 12000, "kind": "數據", "tags": ["財源與預算", "健保給付"], "text": "石部長：2024 年健保總額約 8600 億元，明年將達約 1 兆 0443 億元，三年增加近 2000 億元，約等於開辦 30 年累積的四分之一；資源要投對地方，未來給付將以價值與結果為導向。"}, {"t": 12119, "kind": "挑戰", "tags": ["急性後期照護", "人力培育"], "text": "黃前總院長補充：出院後兩週內 PAC 與居家醫療仍不能重疊；且醫院內治療師留在科內較能創造收入，科部不願放人做居家 PAC，是現實障礙。"}]}, {"id": "2-0", "slot": "13:00", "title": "主題：檢視醫療與社區服務的協作現況與建議", "role": "主持", "speaker": "林右鈞 組長", "org": "衛福部中央健康保險署醫務管理組", "orgType": "政府機關", "t": 15600, "summary": "下午場主題為「檢視醫療與社區服務的協作現況與建議」，由健保署醫務管理組林右鈞組長主持（上月底甫由參議升任組長）。他表示上午各界對健保署的意見已做了筆記，會帶回署內研議並向署長報告；接著逐一介紹五位與談人：台大北護分院黎家銘主任、池上好診所鍾泓翊主任、台灣居家護理暨服務聯盟總會邱青萸理事長、中華聖母基金會黎世宏執行長、一粒麥子基金會張竣傑副執行長，分別代表醫師、物理治療、護理與社福領域的第一線經驗。", "points": [{"t": 15600, "kind": "策略", "tags": ["醫照整合"], "text": "下午場邀請醫師、物理治療、護理及社福領域專家，分享醫療與社區協作的經驗與建議。"}, {"t": 15689, "kind": "政策", "tags": ["健保給付", "醫照整合"], "text": "林右鈞組長表示，上午各界對健保署提出的意見他都記下筆記，會依部長指示帶回研議，並向署長報告。"}, {"t": 15725, "kind": "策略", "tags": ["醫照整合"], "text": "與談人介紹：台大醫院北護分院社區醫療暨長期照護部黎家銘主任，家醫科／老年醫學科主治醫師，台灣在宅醫療學會副理事長。"}, {"t": 15789, "kind": "策略", "tags": ["偏鄉", "醫照整合"], "text": "池上好診所鍾泓翊主任為物理治療師，2017年返鄉台東，從都蘭診所、物理治療所與銀髮訓練教室做起，2025年成立池上好診所，長期深入部落做巡迴醫療與在宅復能。"}, {"t": 15828, "kind": "策略", "tags": ["居家醫療", "醫照整合"], "text": "台灣居家護理暨服務聯盟總會邱青萸理事長，曾任台大醫院護理師與呼吸治療師，為和鄰長照創辦人、衛福部「建構台灣居家護理聯盟網絡」計畫主持人。"}, {"t": 15901, "kind": "策略", "tags": ["醫照整合", "跨部會協作"], "text": "中華聖母基金會黎世宏執行長具近30年醫院與社區長照實務經驗；一粒麥子基金會張竣傑副執行長長期在花東與宜蘭偏鄉服務，並參與A單位個管人員工作手冊編撰。"}]}, {"id": "2-1", "slot": "13:00–15:20", "title": "醫療 X 社區協作機制", "role": "與談", "speaker": "黎家銘 主任", "org": "台大醫院北護分院社區醫療暨長期照護部", "orgType": "醫院", "handout": "https://drive.google.com/file/d/1kDA1bguTnC_3HV9Bc3uB6lBSsU_pwEKR/view", "t": 16072, "summary": "黎家銘主任以醫師角度談如何建立可複製的「醫療X社區協作機制」。他指出醫療與長照在目標、專業語言、資訊系統與給付上是兩個平行世界，並以92歲骨盆骨折阿嬤經居家醫療、居家復能、居服共同照顧後拔管行走的案例說明團隊協作價值。他主張資源應集中於多重共病高急診、重度失能在宅安寧、剛出院三類高風險族群，由醫療團隊與A個管依病況動態輪流主責，並提出Uber式轉介平台、雙向資訊共享、價值導向給付三大方向，介紹北護分院高齡家醫＋高齡個管師的共管流程。", "points": [{"t": 16072, "kind": "策略", "tags": ["醫照整合", "長照3.0"], "text": "長照3.0把醫照整合列為重點目標，黎主任以唯一醫師代表的角度，探討能被複製的醫療與社區協作機制。"}, {"t": 16139, "kind": "挑戰", "tags": ["出院準備", "長照3.0"], "text": "出院到長照服務的銜接時間已大幅縮短，未來目標甚至要出院前就完成；但A個管反映個案若住到外區醫院，是否要跨區到醫院接案，執行上仍有困難，可能需靠遠距等方法。"}, {"t": 16191, "kind": "挑戰", "tags": ["醫照整合"], "text": "醫療與長照本質不同：醫療以急性治療、治癒為目標，用ICD-10診斷與醫囑溝通；長照著重生活照顧與自立支援，以失能、失智評估與照顧組合為語言。"}, {"t": 16247, "kind": "挑戰", "tags": ["數位科技", "醫照整合"], "text": "醫院電子病歷系統封閉、防護嚴密，台大醫院每天約有上百次駭客攻擊；長照資訊系統也將加強憑證認證。兩邊都怕外洩，資料難以整合，寫醫師意見書的醫師也不一定是平常看診的醫師。"}, {"t": 16337, "kind": "挑戰", "tags": ["健保給付", "財源與預算"], "text": "健保是總額下論量計酬，長照是依等級給付上限的「四包錢」，兩邊省下的錢不會流到另一邊，合作先天上有制度困難。"}, {"t": 16396, "kind": "策略", "tags": ["醫照整合", "居家醫療"], "text": "案例：92歲獨居阿嬤半夜在浴室跌倒，骨盆骨折後於門診返家，隔天出現發燒、尿路感染與譫妄，經轉急診住院；家屬拒絕再住院做急性後期照護（PAC），改返家照顧。"}, {"t": 16572, "kind": "策略", "tags": ["居家醫療", "醫照整合"], "text": "返家後由居家醫師與居家護理師定期訪視，A個管開立居家復能由物理治療師到宅，夜間另請本國籍看護；約三個月後拔除尿管、可用四腳助行器出門，回到門診追蹤。"}, {"t": 16596, "kind": "挑戰", "tags": ["長照3.0", "家庭照顧者"], "text": "照顧與專業服務共用同一包額度，個案做復能就壓縮照顧服務時數；照顧者女兒本身也已七十多歲，家庭負擔沉重。"}, {"t": 16650, "kind": "策略", "tags": ["醫照整合", "人力培育"], "text": "此案動用醫師、出備個管、居家護理、物理治療、A個管、居服員、臨床藥師、社工、骨科等多職種，關鍵是要有一個人負責整體設計與資源協調。"}, {"t": 16724, "kind": "數據", "tags": ["醫照整合"], "text": "85歲以上人口預估將從現在約45萬人增至2070年約200萬人，失能率高，不可能每位都這樣密集照顧，必須精準挑選需要整合的個案。"}, {"t": 16755, "kind": "策略", "tags": ["醫照整合", "安寧緩和"], "text": "三大優先族群：多重慢性病、常跑急診與多重用藥者；重度失能、有管路、想在家善終的安寧個案；以及30天內再住院率高的剛出院個案。"}, {"t": 16830, "kind": "挑戰", "tags": ["出院準備", "急性後期照護"], "text": "剛出院個案最危險：居家環境可能缺無障礙與防跌設施、對藥物有誤解、營養不足；衰弱長者正值復健黃金期，復能團隊應盡快進駐，避免再住院。"}, {"t": 16882, "kind": "策略", "tags": ["居家醫療", "醫照整合"], "text": "「動態雙軌主責」：病情不穩、急性問題或多重共病未整合時由醫療團隊主責，居家護理師很適合擔任主導；病情穩定後轉由A個管負責生活照顧期。"}, {"t": 16987, "kind": "挑戰", "tags": ["醫照整合", "人力培育"], "text": "多數A個管沒有醫療背景，全部交給他們壓力很大；照服員常是第一個發現異常的人，需要建立回報醫療團隊的機制。"}, {"t": 17013, "kind": "策略", "tags": ["醫照整合", "居家醫療"], "text": "醫師在長照端的三大角色：評估（減緩失能）、整合（醫療資訊與多重用藥）、銜接（帶動急性與長照之間的服務討論），醫師公會全聯會自2019年起即提出此主張。"}, {"t": 17114, "kind": "政策", "tags": ["出院準備", "在宅急症照護"], "text": "政府已提供出院準備服務、醫師意見書、急性後期照護及在宅急症照護等銜接資源，但由誰負責、如何互相轉介仍待討論。"}, {"t": 17142, "kind": "策略", "tags": ["醫照整合", "失智照護"], "text": "醫師應做周全性老人評估（失智、營養、肌少、多重用藥、靈性與預立醫療意願），並搭配國健署ICOPE指標（行動、營養、視力、憂鬱、聽力、認知）。"}, {"t": 17192, "kind": "建議", "tags": ["數位科技", "社區醫療"], "text": "建議建立像Uber的轉介平台：醫療端把需要上防跌課、據點活動的個案丟出，由政府把關服務單位品質並自動媒合，免得醫護人員到處詢問名額。"}, {"t": 17295, "kind": "挑戰", "tags": ["數位科技", "醫照整合"], "text": "長照端發現異常常只能回報督導、聯絡家屬後送急診；醫療端調藥（如加利尿劑、降血糖藥）後，也無法即時請照服員協助觀察排尿、意識或血糖。"}, {"t": 17441, "kind": "挑戰", "tags": ["醫照整合", "健保給付"], "text": "醫療與長照的三大斷層：出院到服務介入的時間差、醫療與照服員之間缺溝通管道、健保與長照給付脫鉤缺乏合作誘因；連照服員都不一定願意配合共同訪視時間。"}, {"t": 17466, "kind": "建議", "tags": ["健保給付", "財源與預算"], "text": "未來可能需要論人計酬等前瞻性給付，搭配即時通報系統、線上會商與專業分工，並以成果導向的財務獎勵讓大家願意多花時間協作。"}, {"t": 17543, "kind": "策略", "tags": ["數位科技", "醫照整合"], "text": "榮民體系的整合平台可雙向串聯醫療資料與在宅醫療，所有照顧人員（含照服員、外籍看護）都加入並可標記回應者，目前用於榮家個案，黎主任認為做得比台大更好。"}, {"t": 17624, "kind": "策略", "tags": ["醫照整合", "健康台灣"], "text": "北護分院以健康台灣深耕計畫（詹鼎正院長主持）建置高齡家庭醫師與高齡個管師，收案對象為在該院規則看診的長照A個管個案，由護理師背景個管師與醫師定期討論照護計畫。"}, {"t": 17693, "kind": "策略", "tags": ["醫照整合", "數位科技"], "text": "個案都加LINE與個管師聯繫，依風險分級：高風險即時介入、中風險1個月內追蹤、低風險3個月內追蹤；回診時個管師盡量陪同，也補足許多未寫醫師意見書個案的銜接。"}, {"t": 17770, "kind": "建議", "tags": ["醫照整合", "健保給付"], "text": "願景三方向：出院準備與A個管前置對接達到「零天真空期」、建構符合FHIR標準的跨醫療長照雲端平台、以降低再住院與在宅善終為成果的整合型給付試辦。"}]}, {"id": "2-2", "slot": "13:00–15:20", "title": "偏鄉基層診所的醫療與社區協作", "role": "與談", "speaker": "鍾泓翊 主任", "org": "池上好診所", "orgType": "基層診所", "handout": "https://drive.google.com/file/d/1RP3TiTnvS37jHO2RPnDPYAeUXG7EMf4c/view", "t": 17824, "summary": "鍾泓翊主任以台東池上為例，分享偏鄉基層診所如何接住返家個案。台東醫院集中市區，縱谷北端居民就醫困難。以中風後又髖骨骨折的80歲長者為例，自創「RITH（Rehab in the Hotel）」模式：出院前到院評估、把診所樓上民宿改造成無障礙環境，由神經內科、居家醫師與物理治療師每日密集介入，三週後成功返家，費用約醫院一半。他引用國際文獻佐證居家復健成效，並呼籲開放社區型急性後期照護、讓居家醫師能開立PAC處方，使基層團隊獲得制度性給付。", "points": [{"t": 17874, "kind": "策略", "tags": ["偏鄉", "醫照整合"], "text": "團隊合作夥伴包括台灣長照物理治療師學會（健康台灣深耕計畫）、台灣在宅醫療學會、台中慈濟、台南奇美、花蓮門諾、高雄佑榮復健科診所、台東陪你回家協會等。"}, {"t": 17909, "kind": "挑戰", "tags": ["偏鄉"], "text": "池上位於台東縱谷北端，與海岸線的都蘭隔著海岸山脈，醫院集中在台東市區，當地居民取得醫療資源相當困難。"}, {"t": 17977, "kind": "策略", "tags": ["偏鄉", "數位科技"], "text": "診所專科醫師少，透過遠距醫師（台中專科醫師）看診，現場由物理治療師協助評估肌力等即時資訊；居家醫師到宅做吞嚥評估時，也由治療師與護理師一起協作。"}, {"t": 18044, "kind": "挑戰", "tags": ["長照3.0", "居家醫療"], "text": "居家醫師到宅發現需要復能，但申請居家復能層層關卡、速度慢；團隊內若有治療師，就能立即協作介入。"}, {"t": 18075, "kind": "挑戰", "tags": ["出院準備", "家庭照顧者"], "text": "返家困境的關鍵除了環境障礙，還有個案與家屬的心理調適；醫療端能穩住病情、重建生理機能，但回家後的落差有如鴻溝。"}, {"t": 18178, "kind": "策略", "tags": ["急性後期照護", "偏鄉"], "text": "案例：約80歲女性，去年底中風送都會區住院做PAC三週，返家當晚即跌倒，左髖骨折開刀；家屬透過先前社區運動建立的關係，主動聯絡治療師求助。"}, {"t": 18248, "kind": "策略", "tags": ["出院準備", "社區醫療"], "text": "團隊先到醫院探視、與個案家屬建立信任，再邀個案到池上住一段時間養好再返家，相當於「中繼」概念；社區與個案的連結越好，個案越願意配合。"}, {"t": 18280, "kind": "策略", "tags": ["急性後期照護", "偏鄉"], "text": "RITH（Rehab in the Hotel）住宿型復健：利用診所正樓上的民宿，加裝床邊扶手、規劃輪椅動線，先代為準備輔具，環境貼近居家而不像醫院。"}, {"t": 18344, "kind": "策略", "tags": ["醫照整合", "居家醫療"], "text": "多職種介入：神經內科醫師到診所調整用藥並說明，增加個案信心；家醫科在宅醫師用超音波排除膀胱發炎、處理失眠焦慮，減少家屬送急診。"}, {"t": 18412, "kind": "策略", "tags": ["急性後期照護"], "text": "物理治療師上班時間到民宿從床邊轉位訓練開始，再下樓到診所復健，指導如廁與盥洗等日常作息；關鍵是讓個案有動機去動。"}, {"t": 18515, "kind": "數據", "tags": ["急性後期照護", "偏鄉"], "text": "約三週後個案能用四腳拐在少許協助下行走並成功返家，可自行上到二樓，回歸生活。此模式稱為「池上好模式」，結合PAC與小規模多機能。"}, {"t": 18585, "kind": "數據", "tags": ["健保給付", "急性後期照護"], "text": "成本試算：池上好模式總費用約為醫院的一半，但健保給付很少，一般復健僅約50元，須搭配民眾自付才能運作。"}, {"t": 18660, "kind": "數據", "tags": ["社區醫療"], "text": "診所初診約70多人，其中約4成與神經科相關，如巴金森氏症、中風及三高；成立診所的最大吸引力是提供功能性的復健需求。"}, {"t": 18700, "kind": "挑戰", "tags": ["健保給付", "社區醫療"], "text": "單靠儀器復健不夠，需結合日照與關懷據點照顧長輩身心；但法規過時，例如復健處方開立與物理治療給付都跟不上時代。"}, {"t": 18736, "kind": "挑戰", "tags": ["急性後期照護", "健保給付"], "text": "診所具備一對一高強度復健條件，但依現制不符合PAC資格，只能用一般復健給付服務剛中風返家的個案。"}, {"t": 18764, "kind": "建議", "tags": ["急性後期照護", "社區醫療"], "text": "健保署正研議社區型急性後期照護；建議只要在十分鐘生活圈內有專業團隊，就應開放讓其執行。"}, {"t": 18794, "kind": "挑戰", "tags": ["健保給付", "人力培育"], "text": "全台物理治療所近600家，但與健保署簽約的數量很有限，熱血團隊努力做卻得不到給付，希望健保署的研議越快越好。"}, {"t": 18878, "kind": "數據", "tags": ["急性後期照護"], "text": "文獻：2018年研究顯示膝關節炎居家物理治療對疼痛與失能的改善與院內相近；2021年美國骨科醫學會指引強調高齡髖骨折應早期活動、精準處置、預防再骨折。"}, {"t": 18948, "kind": "數據", "tags": ["急性後期照護", "家庭照顧者"], "text": "2020年系統性回顧顯示中風居家復健在行走速度與平衡上不劣於醫院，關鍵是病人動機與定期追蹤；個管很忙，往往要靠熱心家屬才能維持成效。"}, {"t": 18979, "kind": "數據", "tags": ["急性後期照護"], "text": "澳洲以居家病床取代急性後照護病床，對65歲以上長者高強度復健安全且具成本效益，並降低譫妄與死亡率；2026年BMJ發表的中風後跌倒試驗（FAST），居家PT/OT方案減少約三分之一跌倒。"}, {"t": 19037, "kind": "策略", "tags": ["日本經驗", "社區醫療"], "text": "借鏡日本，「家」不一定是老家，也可能是醫院或社區據點；要思考個案真正要回到哪裡，並強化與醫師的連結。"}, {"t": 19070, "kind": "數據", "tags": ["急性後期照護", "健康台灣"], "text": "參與健康台灣深耕計畫的城鄉多元PAC服務模式：兩位人工髖、膝關節置換個案於術後第五週才因疼痛求診介入，在上限12次的高強度復健下，四週內巴氏量表由40分進步到100分。"}, {"t": 19134, "kind": "挑戰", "tags": ["急性後期照護"], "text": "現有急性後期整合照護雖有住院、日間照護、居家模式，但大部分仍集中在住院模式。"}, {"t": 19198, "kind": "建議", "tags": ["急性後期照護", "居家醫療"], "text": "池上好以門診復健為基礎，由居家醫師以個案為中心承擔連結角色，結合復健、復能與社區中繼；建議讓居家醫師能開立PAC處方，提供制度性給付支援。"}, {"t": 19241, "kind": "建議", "tags": ["居家醫療", "健保給付"], "text": "居家醫療是社區與醫院之間的「手套」；治療人員應能整合運用儀器、徒手與運動訓練，而非被給付限制只能做電療。"}]}, {"id": "2-3", "slot": "13:00–15:20", "title": "醫療與社區協作：居家護理的角色", "role": "與談", "speaker": "邱青萸 理事長", "org": "台灣居家護理暨服務聯盟總會", "orgType": "專業團體", "handout": "https://drive.google.com/file/d/1xt7fVK0-WnwmFRT001iYfvVVCu34jgOC/view", "t": 19316, "summary": "邱青萸理事長從居家護理第一線與政策溝通的角度，談以「家」為場域的醫療與社區協作。她把個案分為早期衰弱、中期居家整合照護、後期安寧與在宅急症三階段，指出各階段主責單位不同且混亂，早期衰弱者八成沒有主責、出院個案30天內再急診再住院比例仍高。她強調居護師每月固定進家，最適合擔任串接協作的舵手，全台居護所也願轉型為「家庭護理師」；並倡議出院前7日包裹銜接、返家3日內首次到宅、30日確認成果的制度，期望長出台灣自己的社區照護模式。", "points": [{"t": 19348, "kind": "策略", "tags": ["居家醫療", "人力培育"], "text": "台灣居家護理暨服務聯盟總會聚集最多從事社區照護的護理師與跨專業團隊，邱理事長稱其為全台最大的社區照護NGO。"}, {"t": 19381, "kind": "挑戰", "tags": ["居家醫療", "醫照整合"], "text": "居家個案需求多元：慢性衰弱、安全進食、失智、傷口、足部、安寧、在宅急症，單一專業人員不可能全部具備能力，即使同職種專長也不同。"}, {"t": 19449, "kind": "挑戰", "tags": ["人力培育", "居家醫療"], "text": "整合銜接面臨兩大問題：人力與能力；若持續如此，專業人員不敢獨自進家服務，必須依需要組隊。"}, {"t": 19482, "kind": "策略", "tags": ["醫照整合", "居家醫療"], "text": "個案分三階段：早期為ICOPE評估出的衰弱者；中期為穩定但無法外出就醫、需居家醫療或居護團隊者；後期為安寧或不需住院的急性重症（在宅急症）。"}, {"t": 19553, "kind": "策略", "tags": ["居家醫療", "健保給付"], "text": "中期居家整合照護的主責可以是診所、醫院附設居護所或獨立型居護所，擔任個案管理的key person（個管費約每年600元），不論從哪裡來都能接住。"}, {"t": 19580, "kind": "挑戰", "tags": ["健康台灣", "社區醫療"], "text": "早期衰弱者目前靠「大家醫888計畫」由診所主責，但只涵蓋有規則用藥、願意就醫的人；ICOPE篩出更多衰弱者後，其他約八成沒有主責。"}, {"t": 19645, "kind": "挑戰", "tags": ["安寧緩和", "在宅急症照護"], "text": "沒有主責時，家庭照顧者或願意扛起的人就成了主責，非常危險；安寧期多由居護所主責、醫師支援，在宅急症則由診所與醫療院所主責。"}, {"t": 19735, "kind": "建議", "tags": ["數位科技", "醫照整合"], "text": "資訊整合要把健保醫療資訊雲端與長照資料串起來，在最需要溝通時另建共訪溝通平台；只要國衛院、健保署的系統能介接各家資訊廠商即可。"}, {"t": 19763, "kind": "挑戰", "tags": ["社區醫療", "失智照護"], "text": "許多長照個案不規則用藥、生活習慣難改變，診所醫護一句指示說不動；從衰弱開始的銜接存在缺口，沒有人支援以預防失能失智。"}, {"t": 19826, "kind": "數據", "tags": ["出院準備", "長照3.0"], "text": "出院到長照銜接已從51天縮短到4天，但出院準備個案使用長照者，約23%在30天內會再急診或再住院，這部分改善不夠快。"}, {"t": 19896, "kind": "挑戰", "tags": ["出院準備"], "text": "能接受出院準備服務的個案比例有限（講者提到約18%），且幾乎都是長照、獨老等高風險難照顧個案；30天內再急診、再住院的責任歸屬醫院或長照都說不清。"}, {"t": 19945, "kind": "數據", "tags": ["長照3.0", "出院準備"], "text": "長照銜接指標由4天朝2天、0天推進，第一線回饋已進步到約1天，但照護問題本身仍然存在。"}, {"t": 19983, "kind": "建議", "tags": ["安寧緩和", "健保給付"], "text": "安寧照護應依個案是急性醫療需求多或照護問題多來規劃配套；約五個學協會正在溝通，要給健保署更好的建議，目標是社區照護而非誰拿的錢多。"}, {"t": 20023, "kind": "建議", "tags": ["醫照整合"], "text": "每個階段都應明確有1到2個主責單位，不限診所、醫院或居護所；接到個案就該負責接好，讓每個角落都老有所終。"}, {"t": 20055, "kind": "挑戰", "tags": ["長照3.0", "人力培育"], "text": "同一家庭照護需求轉變是正常歷程；長照2.0已近十年、3.0剛啟動，需要Link Worker（連結者），但問題是人力與能力從何而來。"}, {"t": 20123, "kind": "策略", "tags": ["居家醫療", "人力培育"], "text": "穩定的中重症個案每月都有居護師進家1到2次，相較個管約六個月訪一次、居服一週去2到3次但醫療能力較弱，居護師最適合擔任串接協作的舵手。"}, {"t": 20161, "kind": "數據", "tags": ["居家醫療", "人力培育"], "text": "11月7日「建構台灣居家護理聯盟網絡」計畫成果發表約400人參加、85%為護理師，全台約五分之二居護所到場；問到是否願轉型，幾乎全數舉手。"}, {"t": 20193, "kind": "策略", "tags": ["居家醫療", "人力培育"], "text": "居護所過去為騰出醫院病床而到家換管，如今換管需求已減少，正轉型為以民眾為中心、以家庭為單位的「家庭護理師」。"}, {"t": 20285, "kind": "策略", "tags": ["醫照整合"], "text": "歐洲多國已做好照護銜接，講義舉法國Prado（出院前安排社區醫護與首次追蹤）、瑞士ATC（出院後最長兩週過渡照護）為例。"}, {"t": 20300, "kind": "數據", "tags": ["出院準備", "居家醫療"], "text": "出院個案長照專業人員首次進家平均約7天，居護師首次進家約15天；返家缺病床、點滴，易脫水、壓傷，常在14天內發燒、14到30天內再住院，錯過黃金期。"}, {"t": 20368, "kind": "建議", "tags": ["出院準備", "健保給付"], "text": "倡議（非核定給付）：以一個包裹支持出院前共同開案交班、返家3日內首次到宅評估、前7日跨團隊協作，並於出院30日確認目標，追蹤急診再就醫與非計畫再住院率。"}, {"t": 20400, "kind": "建議", "tags": ["醫照整合", "長照3.0"], "text": "跨體系在地團隊應一起工作，不分醫療、居護所或長照；她相信台灣不必照搬日本、法國或英國模式，可以長出自己的社區照護模式。"}]}, {"id": "2-4", "slot": "13:00–15:20", "title": "醫療與社區服務協作", "role": "與談", "speaker": "黎世宏 執行長", "org": "中華聖母社會福利慈善事業基金會", "orgType": "社福團體", "handout": "https://drive.google.com/file/d/1kZjAwIBp6kImSUV7F_ky_UCUljaVtKXq/view", "t": 20434, "summary": "黎世宏執行長以「返家後的生活」檢驗醫照整合。他指出長照3.0讓出院準備、PAC、居家醫療與在宅急症都動起來，出院銜接天數從51天縮到4天、目標2天，但「快」不等於照顧足夠：家屬難參與、居服人力無法待命、服務碼別受限、A個管與照專人力不足、長照資料散在民間業者。他以一位獨居中風個案說明轉銜落差，主張醫照協作成果不能只看再住院率，也要看生活改善與家庭負荷；建議明確分工與交接、雙向資訊、盤點給付補協調費用、地方分階段試辦。", "points": [{"t": 20515, "kind": "政策", "tags": ["長照3.0", "醫照整合"], "text": "從長照0.0一路做到3.0，他認為3.0的關鍵是醫療端與長期照顧端怎麼做好接軌。醫照協作的目的是讓有醫療與照顧需求的人回到熟悉的生活環境，持續獲得支持。"}, {"t": 20552, "kind": "挑戰", "tags": ["出院準備", "人力培育"], "text": "過去醫院不重視出院準備小組，健保沒有點數、拿不到錢，人力多是快退休的護理人員；政策調整後才逐步擴充，但願意投入的人仍少。"}, {"t": 20616, "kind": "挑戰", "tags": ["家庭照顧者", "醫照整合"], "text": "家屬是醫照協作裡最常處理不好的一塊；長照3.0雖納入家庭照顧者，但醫院做決策時常找不到家屬。"}, {"t": 20647, "kind": "建議", "tags": ["數位科技", "醫照整合"], "text": "他舉口罩實名制三天就上線為例，質疑醫療與長照資訊為何多年無法串接；期待未來插一張健保卡，醫療端交代的事長照端看得到，長照服務紀錄醫療端也看得到。"}, {"t": 20725, "kind": "策略", "tags": ["醫照整合", "出院準備"], "text": "醫照協作四個目的：照顧不中斷、把治療成果落實到日常生活（如中風後在醫院練走，回家能如廁、洗澡、外出）、支持本人與家庭的選擇、及早回應變化以減少可避免的危機。"}, {"t": 20759, "kind": "挑戰", "tags": ["人力培育", "長照3.0"], "text": "政策期待A個管扮演跨專業模式的主導者，但許多A個管連長照服務項目都不熟，更看不懂醫療診斷、藥物與BID、TID等醫囑用語。"}, {"t": 20868, "kind": "挑戰", "tags": ["出院準備", "長照3.0"], "text": "醫院要求出院即刻銜接時，他直言居家服務不可能有閒置的居服員待命，前一天通知也很難派出人；輔具與交通接送（如復康巴士）則比較容易配合。"}, {"t": 20929, "kind": "數據", "tags": ["出院準備", "長照3.0"], "text": "出院銜接長照的等待從過去51天縮到官方公布平均4天，2026年政策目標為2天（講義：截至2025年底242家醫院參與）。他提醒平均值不能代表每個地區與高風險個案，快也要回應真正的急迫需求，不只是縮短天數。"}, {"t": 20963, "kind": "挑戰", "tags": ["人力培育", "跨部會協作"], "text": "制度再好沒有人、或人被各種規定綁住都沒用：口腔照護專業長年進不了機構，因牙醫師公會不放；OT、PT過去要等醫師開單；一個人插三四條管，換管卻要不同專業分別處理。"}, {"t": 21073, "kind": "策略", "tags": ["急性後期照護", "出院準備"], "text": "個案：69歲獨居女性，腦梗塞左側偏癱，約一個半月歷經急性住院、轉入PAC病房復健後出院。院內有營養師、PT、OT、心理師、社工、出院準備護理師、PAC個管師等介入；出院時CMS第4級，持助行器可走約50公尺，安排沐浴、備餐、陪同就醫、居家復能、交通接送與輔具。"}, {"t": 21109, "kind": "挑戰", "tags": ["出院準備", "家庭照顧者"], "text": "這個個案轉銜的三個難題：主要家屬工作忙、不易到院，服務細節要多次確認；出院當下居家服務只能派獎勵計畫中的特定碼別，難回應個別需求；出院準備有時效壓力，但不是每位個案都同樣急迫。"}, {"t": 21149, "kind": "策略", "tags": ["出院準備", "長照3.0"], "text": "嘉義市以「出院宅急便」讓專業人員先進入家中，優先安排沐浴、陪伴與餐食；出院後實際需求常與初評有落差，再由A個管家訪後與家屬調整服務內容與頻率。"}, {"t": 21207, "kind": "挑戰", "tags": ["長照3.0", "人力培育"], "text": "出院後交接給A個管或照專接得起來嗎？他回顧長照從第一代ABC到第二代的演變，指出目前有縣市照專因缺人而不做訪評、也有縣市訪評外包，照專留任率低，權責與追蹤難如預期銜接。"}, {"t": 21280, "kind": "挑戰", "tags": ["數位科技"], "text": "醫療各院有自己的病歷系統並以同格式上傳健保；長照則沒有政府自建的管理系統，全國每一筆服務資料都鍵在民間資訊業者的系統上，萬一被駭，責任歸屬不明。"}, {"t": 21386, "kind": "建議", "tags": ["數位科技", "居家醫療"], "text": "期待插健保卡就能看到這次居家服務內容、居服員想請醫師交代的事、病情變化，醫師無論在宅或回診都能直接轉成可執行的行動。"}, {"t": 21414, "kind": "挑戰", "tags": ["人力培育"], "text": "各類人力都往利潤高的地方流動，協調、假日與臨時增援等資源接不上；數字呈現的成果與深入檢視後的實況常不一樣，需要持續追蹤。"}, {"t": 21456, "kind": "建議", "tags": ["醫照整合", "家庭照顧者"], "text": "返家後的評估缺口：生活功能（吃飯、如廁、移動、社會參與）是否改善、家屬照顧負荷是否減輕、沒接上服務的人後來怎麼了、獨居與偏鄉等複雜需求者是否同樣受益。"}, {"t": 21492, "kind": "建議", "tags": ["急性後期照護", "醫照整合"], "text": "醫療端已發展在宅醫療、在宅急症照護、在宅安寧，PAC也從過去因給付不足而失敗，到現在有居家PAC、機構PAC；但仍是長照做長照、醫療做醫療。醫照協作的成效不該只看重複住院率，應把長照面向一起納入檢視。"}, {"t": 21590, "kind": "建議", "tags": ["出院準備", "醫照整合"], "text": "許多個案跨縣市就醫（如嘉義市被嘉義縣包圍），建議出院前讓在地長照單位及早參與返家討論（跨縣市可用視訊），高風險個案預先評估住家環境與家庭照顧能力，並設協調窗口追蹤未解決的需求。"}, {"t": 21657, "kind": "建議", "tags": ["數位科技", "醫照整合"], "text": "責任醫療團隊不必等個案回院，可透過長照的資訊共享追蹤狀況；雙向資訊要有明確介接系統與資安防護，也要準備系統當機時的備援（含紙本或文字版）。"}, {"t": 21730, "kind": "建議", "tags": ["財源與預算", "醫照整合"], "text": "經費與人力需一起到位：先盤點既有給付、討論合理成本，再補足跨單位協調缺口（共同訪視、會商、臨時增援、偏鄉支援）；建議分階段由地方先試辦，從高風險返家個案小規模開始，再評估擴大。"}, {"t": 21765, "kind": "策略", "tags": ["日本經驗", "醫照整合"], "text": "台灣機構每年出國參訪，但看完很少真正落實。可借鏡的原則包括WHO ICOPE、英格蘭短期復原與轉銜樞紐、美國PACE，以及日本以地方生活圈串連醫療轉介、據點與長照，避免一案多管。"}, {"t": 21833, "kind": "建議", "tags": ["長照3.0", "家庭照顧者"], "text": "建議整合居家、日照與小規機作為社區醫照協作的支撐點（例如兩天居家、三天日照）。中央放寬小規機夜間床數，但他認為問題不在床數，而在A個管不知如何轉介夜間照顧、家屬也不覺得有必要。"}, {"t": 21898, "kind": "建議", "tags": ["數位科技"], "text": "大家都在談把資料AI化做預測，他提醒要先有一致的共同欄位（藥物變更、功能表現、未滿足需求）與明確回應機制：誰接收、何時回應、如何確認處理完成，再用工具減少資訊落差。"}, {"t": 21930, "kind": "建議", "tags": ["跨部會協作", "人力培育"], "text": "結論：儘快解決跨單位、跨部門、跨署的問題，給予合理支付，整合人力，不要大家都在做個案管理，醫照整合才能邁入下一階段。"}]}, {"id": "2-5", "slot": "13:00–15:20", "title": "醫照共案協作", "role": "與談", "speaker": "張竣傑 副執行長", "org": "一粒麥子社會福利慈善事業基金會", "orgType": "社福團體", "handout": "https://drive.google.com/file/d/1cVOjQSHg_bvL_9fleD4mziS-BJPp6N4W/view", "t": 21966, "summary": "張竣傑副執行長談醫照「共案」：共案不應只是分工，分工會變成各做各的多團隊模式，應像跨專業團隊一樣有共同目標、互相補位。他指出結構性問題：A個管手上120到150案沒時間連結、出院銜接獎勵沒有涵蓋所有實際出力的單位、術語文化差異與缺乏指引。接著分享宜蘭兩種模式：羅東「醫照微聚落」把居家醫療、居家護理與ABC放在同一棟建築常態開會；大同鄉與羅東聖母醫院合作，結合部落文健站、志工與衛生所。他強調醫照資訊平台核心要有能即時討論的「共筆」區。", "points": [{"t": 22001, "kind": "策略", "tags": ["醫照整合"], "text": "共案常被理解為分工就好，但分工後容易變成多團隊模式、各做各的；應像跨專業團隊一樣有共同目標，放下本位、互相補位，溝通是為了找共識，而不是說服對方。"}, {"t": 22108, "kind": "策略", "tags": ["醫照整合", "跨部會協作"], "text": "同體系內（如ABC）是跨專業合作，醫療與長照則是跨體系共開個案，關鍵問題之一是誰當個管。"}, {"t": 22214, "kind": "挑戰", "tags": ["人力培育", "財源與預算"], "text": "醫照之間的對話要花時間、精神與管理成本，但A個管手上約120到150案，評鑑時常被問為何沒和在宅醫師深入討論，實際上根本沒時間做資源連結。"}, {"t": 22286, "kind": "建議", "tags": ["出院準備", "財源與預算"], "text": "出院準備銜接長照獎勵計畫的對象包括醫院、A單位、居家服務與交通接送等單位，但實際卡關在B單位沒有人力，要臨時長出人、鼓勵居服員跑更遠都是成本；他主張每個有貢獻的環節都應納入獎勵，大家共利才有成果。"}, {"t": 22350, "kind": "挑戰", "tags": ["醫照整合"], "text": "四年前在同一個研討會就談醫照合作，進展不大；若沒有制度誘因，醫照協作就只能靠熱情「做功德」。"}, {"t": 22383, "kind": "建議", "tags": ["數位科技", "醫照整合"], "text": "若要建平台串接健保、長照，甚至社福（如獨居老人）資料，裡面一定要有「協作共筆」區，不只上傳資料，還要能在上面討論，沒有討論就沒有互動與補位。"}, {"t": 22447, "kind": "建議", "tags": ["人力培育", "醫照整合"], "text": "各專業看事情的角度不同（評鑑委員之間也看得出差距），制度上應設計更多對話機會，例如共筆與個案研討。"}, {"t": 22483, "kind": "建議", "tags": ["醫照整合", "人力培育"], "text": "合作不會自己冒出來。就像A個管在中央手冊出來前大家亂寫計畫、亂連結資源，醫照合作也需要指引；建議中央或委託學會、協會編寫簡易版協作指引，說明如何找夥伴、連結目的，並附共同協作案例。"}, {"t": 22629, "kind": "建議", "tags": ["人力培育"], "text": "醫療與長照彼此的專業術語與溝通方式不同，可透過教育訓練拉近彼此對專業範疇的認知。"}, {"t": 22673, "kind": "策略", "tags": ["醫照整合", "偏鄉"], "text": "宜蘭兩種模式：一是「醫照微聚落」（社區型健康照護同盟），區域內有多位能做在宅醫療的醫師，長照端主動邀請、遇有居家醫療需求主動連結；二是區域只有一家主要醫療團隊，如大同鄉以羅東聖母醫院資源為主，彼此互通有無。"}, {"t": 22739, "kind": "策略", "tags": ["醫照整合", "居家醫療"], "text": "自民國108年起與羅東一家居家醫療診所合作，把A單位、B單位、巷弄長照站與醫師、居家護理放在同一棟建築，並拉進復能專業；不是每個個案臨時組隊，而是一個可以馬上動起來的固定團隊。"}, {"t": 22812, "kind": "策略", "tags": ["居家醫療", "醫照整合"], "text": "居家醫療與長照的雙向轉介對照顧者幫助很大。例如一位阿嬤領了一堆藥隨意吃，醫師以為無效而加量，居服員發現後通報醫師重新評估；反過來，長者有狀況時醫師能先做第一線處理，不必馬上送急診。"}, {"t": 22923, "kind": "策略", "tags": ["醫照整合"], "text": "與其爭論誰是主責、誰是協力，不如各自先把自己的照顧計畫或治療目標做好，再定期開會討論；同在一處就能常見面，不靠系統也能形成共識。"}, {"t": 22951, "kind": "策略", "tags": ["社區醫療", "日本經驗"], "text": "據點設計成居民可以進來喝茶、問問題的公共空間，各單位看板清楚標示；受日本在宅醫療參與地方創生的啟發，常辦社區講座、音樂會、露天電影，和鄰里建立夥伴關係。"}, {"t": 23072, "kind": "策略", "tags": ["偏鄉", "醫照整合"], "text": "大同鄉模式把在地經營十多年的社區互助系統拉進醫照合作，並嘗試結合社會處方、在宅急症照護（HAH）與雙向綠色通道。"}, {"t": 23108, "kind": "建議", "tags": ["出院準備", "在宅急症照護"], "text": "轉給長照不代表萬能。建議出院準備端對高風險病人仍要保留醫療追蹤，與長照團隊結合，設計雙向轉介與綠色通道，並由A、B單位即時回報生活照顧訊息，以降低短期再住院風險。"}, {"t": 23144, "kind": "策略", "tags": ["偏鄉", "居家醫療"], "text": "大同鄉面積約新北市三分之一、診所只有一兩家，因此運用遠距醫療並與衛生所結盟，希望與聖母醫院合作成為在地樞紐（hub），把在地團體與醫療資源都拉進來，目前試行約半年。"}, {"t": 23207, "kind": "策略", "tags": ["偏鄉", "社區醫療"], "text": "早年與社家署合作偏鄉社區整合方案，在地培育了六個部落成立文健站或據點，現多已是巷弄長照站；這些具文化敏感度的在地團體一起進入團隊，發現長者有健康促進、預防延緩失能需求時轉介很快。"}, {"t": 23274, "kind": "策略", "tags": ["偏鄉", "家庭照顧者"], "text": "結合志工、村里長與社區組織組成類似守望相助的團隊，平時當部落的「偵測器」，發現長輩異狀就通報A個管，再詢問醫療團隊是否需介入；因救護到南山部落約需一小時，也培訓志工做第一線緊急處理。"}, {"t": 23341, "kind": "策略", "tags": ["數位科技", "醫照整合"], "text": "因距離遠、面對面討論不易，正與國衛院計畫合作建置醫療與長照整合資訊系統，由智齡科技（Jubo）協助，醫療端以羅東聖母醫院、長照端以一粒麥子為主，預計在南港醫療展展示。"}, {"t": 23483, "kind": "建議", "tags": ["數位科技"], "text": "系統的核心不是資料串接或單向轉介，而是可即時討論的協作共筆（留言或即時通話）；只有雙向交流討論，才能真正互相補位。"}]}, {"id": "2-6", "slot": "15:20–16:00", "title": "下午綜合座談", "role": "座談", "speaker": "", "org": "", "orgType": "", "t": 23553, "summary": "下午綜合座談由健保署林右鈞主持。他先說明健保署正規劃居家（在宅）資訊整合平台，依衛福部FHIR標準串接醫療、居家醫療、長照與護理紀錄，但受VPN封閉網路與A級資安要求限制。與會者提問聚焦：醫院出院準備是否有社工與標準配置、如何讓醫院把PAC個案下轉社區、物理治療所不在長照交通接送範圍、民宿作為復健居所、照服員業務邊界與心理支援。林右鈞回應部長已要求全面盤點PAC卡點，健保方案多以建議而非硬性規定人員組成；與談人則補充實務解法與政策建議。", "points": [{"t": 23588, "kind": "挑戰", "tags": ["數位科技", "健保給付"], "text": "林右鈞：健保申報資料雖較一致，但與長照、護理資料格式、存放方式、網路都不同；健保署為A級資安機關、走封閉VPN，外部系統難接入，署內已把部分資訊人力移往資安。"}, {"t": 23754, "kind": "政策", "tags": ["數位科技", "居家醫療"], "text": "林右鈞：健保署正規劃居家（在宅）資訊整合平台，希望呈現病人醫療資訊、家醫收案、居家醫療、長照執行情形與護理紀錄，並有聯絡功能（回應張竣傑的共筆建議）；平台將遵循衛福部FHIR國際標準，建置完成後試營運。難題在放在VPN內外部查不到、放到外面又有風險，以及各資訊廠商介接能力不一。"}, {"t": 23903, "kind": "建議", "tags": ["日本經驗", "出院準備"], "text": "旅日多年從事社區照顧培訓的與會者提問：日本佐久以國中學區、長者步行約30分鐘可達為一個社區，共有六個站，醫院設地域醫療部並有完整PT、OT、ST；台灣醫院出院準備是否有在宅醫療部門與醫務社工？日照、機構常拿不到診斷書，責任如何釐清？日本是用加算獎勵而非處罰。"}, {"t": 24138, "kind": "建議", "tags": ["急性後期照護", "醫照整合"], "text": "台灣長期照顧物理治療學會理事長：學會與屏東縣物理治療師公會完成健康台灣相關計畫，社區型PAC對中風與脆弱性骨折個案成效好又省錢；但難在醫院不願把想回家的個案下轉社區，詢問健保署能否用政策協助並更彈性開放。"}, {"t": 24350, "kind": "政策", "tags": ["急性後期照護", "健保給付"], "text": "林右鈞回應：部長今年已召開多次會議討論PAC如何放寬，但要求先做全面盤點，以人數最多的腦中風為例，從急性醫療往下每一段卡在哪裡，也包含衰弱老人；健保署會考慮增加下轉誘因，但誘因不一定推得動，放寬也可能衍生其他問題，重點是了解病人後續真正需要什麼，而非只縮短銜接天數。"}, {"t": 24471, "kind": "挑戰", "tags": ["出院準備", "人力培育"], "text": "黎世宏（以社工師全聯會副理事長身分）回應：出院準備小組公告人員未列社工師，因社工師不屬醫事人員；中央說列出的職種只是舉例、不限制社工加入，部分醫院確有社工，但人力比與獎勵誘因不足，醫院不願投入更多職種。"}, {"t": 24658, "kind": "挑戰", "tags": ["出院準備", "日本經驗"], "text": "黎世宏：台灣出院準備沒有標準配備，也沒有依床數訂的人力比。提問者補充日本另有再住院相關加算，並強調醫院應延續社區提供的照顧資訊，而不是一進醫院就全部重來。"}, {"t": 24758, "kind": "政策", "tags": ["復健病房", "健保給付"], "text": "林右鈞：健保方案多以「如社工人員等」建議團隊組成，不硬性規定，因醫療與照護人力短缺，寫死會讓部分醫院（尤其偏鄉）無法推動；今年推出的復健病房試辦計畫即參考日本回復期復健病院模式，日本出院準備的做法未來也可參考，但引進台灣後模式可能不同。"}, {"t": 24888, "kind": "策略", "tags": ["急性後期照護", "居家醫療"], "text": "鍾泓翊補充：該計畫的12次服務由治療師帶著儀器進到家中，補上出院後到回診之間約一個月的空窗，先提升行動力，再讓個案到社區物理治療所使用懸吊、電療等設備；居家醫師常發現病人需要復健卻沒有給付，只能靠熱血。"}, {"t": 25058, "kind": "挑戰", "tags": ["長照3.0", "急性後期照護"], "text": "鍾泓翊與另一位執行計畫的與會者指出：長照交通接送只給付從家裡到醫療機構，物理治療所屬「醫事機構」（與藥局、檢驗所同類）而不能使用，呼籲應以病人需要為準，而非被名詞限制。"}, {"t": 25179, "kind": "建議", "tags": ["人力培育", "重症兒童"], "text": "孫秘書長提問：吞嚥訓練、抽痰等業務誰能做常有爭議，特教學校只能聘專案護理師，未來人力不可能足夠；建議重新定義邊界，在羅東這類有醫師、護理師後援的模式下，放寬照服員可執行的部分業務，並詢問張竣傑有哪些成功案例；另詢問鍾泓翊民宿的輔具與無障礙改善費用如何處理。"}, {"t": 25384, "kind": "挑戰", "tags": ["長照3.0", "偏鄉"], "text": "另一位與會者提問：民宿是否算長照交通車的「居住地」？全人照顧還有心理支援需求，例如前往心理諮商所的交通與服務是否也應被看見？"}, {"t": 25486, "kind": "策略", "tags": ["偏鄉", "急性後期照護"], "text": "鍾泓翊回應：偏鄉病人為就醫在醫院附近租屋並不新鮮；池上能發展民宿復健，靠遠距醫療與奇美醫院醫師報備支援看診，加上觀光名氣與好環境。輔具在民宿用完可直接帶回家；因長照無障礙申請要等，住宿採自費、可選房型，在地農會支持，民宿給長住者約五折優惠。心理面則先營造讓人願意復健的環境，並建議開放遠距心理諮商。"}, {"t": 25756, "kind": "數據", "tags": ["長照3.0", "人力培育"], "text": "黎世宏：長照其實有心理支援相關C碼，但能執行的專業人員少、單價高；交通接送更缺，他的日照30人中每天有21人需接送，兩輛車都不夠，長照交通約車常要提前一到兩週；臨床心理師在醫院排程至少一個多月。"}, {"t": 25877, "kind": "策略", "tags": ["醫照整合", "失智照護"], "text": "張竣傑回應：醫照協作對長照端幫助最大的是帶管路出院、明顯BPSD、壓傷傷口等個案；共案不一定是共開個案，也可以是專家諮詢關係，和在宅醫師團隊熟悉後，臨床問題能馬上得到回應。"}, {"t": 25969, "kind": "策略", "tags": ["長照3.0", "跨部會協作"], "text": "張竣傑：心理諮商碼開不出來或資源少時，可先洽在地社區心衛中心或張老師；長照交通接送（DA01）嚴格限定就醫（有醫師診療），去物理治療所不行，實務上若有身障證明可改用復康巴士變通。"}, {"t": 26071, "kind": "建議", "tags": ["急性後期照護", "居家醫療"], "text": "黎家銘：現行PAC限發病一個月內、住院72小時以上並由上游醫院轉介，個案一旦出院回家就卡死；建議讓願意接手的居家團隊（醫師、護理師、PT、OT等）憑出院病歷摘要也能開立。目前只能改用長照居家復能（約每週一次PT）或交通接送回醫院復健。"}, {"t": 26148, "kind": "建議", "tags": ["急性後期照護", "醫照整合"], "text": "黎家銘：北護分院透過PAC跨院座談會呈現良好復健成效，連較遠的亞東、萬芳醫院也願意轉介；團隊間原本互不認識、醫院也怕轉出去照顧不好被罵，建議中央協助建立媒合工具與互信轉介管道，讓社區型、居家型PAC團隊更容易承接。"}, {"t": 26240, "kind": "策略", "tags": ["居家醫療", "人力培育"], "text": "邱青萸：多運用居護所，他們每月到案家一到兩次，是很好的支援者；目前正在培訓居家護理師轉型為「家戶護理師」的概念，未來一兩年居護所會有越來越多改變。"}, {"t": 26276, "kind": "政策", "tags": ["醫照整合", "長照3.0"], "text": "林右鈞總結：各位的意見會帶回健保署討論，涉及長照的議題也會帶到衛福部一起研議。"}]}]}, {"id": "d2", "date": "11/15（日）", "short": "11/15", "video": "PiKwuQceCC0", "theme": "健保復健病房試辦計畫／醫療照顧需求重症兒童", "sessions": [{"id": "3-0", "slot": "09:00", "title": "主題：全民健康保險復健病房試辦計畫執行分享", "role": "主持", "speaker": "馬海霞 副理事長", "org": "台灣社會福利總盟", "orgType": "主辦單位", "t": 1230, "summary": "Day 2 第一場主題為「全民健康保險復健病房試辦計畫執行分享」，由具職能治療師背景、長年關注身障者與燒燙傷者照顧權益的台灣社會福利總盟馬海霞副理事長主持。她提到總盟每年在陳節如理事長帶領下赴各國參訪復健病房與急性後期照護（PAC），希望借鏡國外經驗強化現有制度，並感謝部長、署長擴大復健病房試辦計畫。接著介紹主講人健保署陳亮妤署長，以及臺北市立聯合醫院陳良城副院長、桃園長庚陳靖倫主任、衛福部臺中醫院蔡明妙主任、員郭醫院郭鐘添院長四位與談人。", "points": [{"t": 1230, "kind": "策略", "tags": ["復健病房"], "text": "第二天第一場聚焦全民健保復健病房試辦計畫，目的是了解試辦目前的推展狀況，由職能治療師出身的馬海霞副理事長主持。"}, {"t": 1296, "kind": "策略", "tags": ["復健病房", "急性後期照護"], "text": "馬副理事長表示，總盟每年在陳節如理事長帶領下到多國參訪復健病房與 PAC 做法，希望在原有制度上借鏡國外經驗再多做一些。"}, {"t": 1331, "kind": "政策", "tags": ["復健病房"], "text": "感謝署長與部長讓復健病房試辦計畫得以擴大；本場先由署長專題演講，再由四家試辦醫院分享執行經驗。"}, {"t": 1367, "kind": "策略", "tags": ["復健病房"], "text": "主講人陳亮妤署長為約翰霍普金斯大學公共衛生博士，曾任衛福部心理健康司司長，現任健保署署長。"}, {"t": 1396, "kind": "策略", "tags": ["復健病房"], "text": "與談人：臺北市立聯合醫院行政副院長兼復健科主任陳良城（陽明院區）；長庚醫療體系復健科副部主任、長庚大學副教授陳靖倫，桃園長庚復健服務有兩百多床，試辦計畫約 40 床。"}, {"t": 1509, "kind": "策略", "tags": ["復健病房"], "text": "另兩位與談人：衛福部臺中醫院復健科主任暨復健病房計畫主持人蔡明妙（兼兒童發展聯合評估中心主任），以及員郭醫院郭鐘添院長；主持人稱員郭以病人回歸原本生活為目標訂定復健計畫，是值得期待的模式。"}]}, {"id": "3-1", "slot": "09:00–09:30", "title": "專題演講：全民健康保險復健病房試辦計畫", "role": "主講", "speaker": "陳亮妤 署長", "org": "衛福部中央健康保險署", "orgType": "政府機關", "t": 1581, "summary": "陳亮妤署長以「高齡化下的健保新政」為題，指出台灣從高齡到超高齡社會只花 7 年，政策要從「照顧失能」轉向「減少失能」。健保總額連續三年 5.5% 高推估，明年挹注護理量能、在宅急症、復健病房等醫療銜接長照。以大數據破除長者浪費醫療的迷思，強調三高與中風防治；復健病房參考日本小倉模式，高 OT/PT 人力比、居家模擬訓練寫入支付標準，首年 3 億元、9 月開辦 10 家、明年再增 26 家經費。另介紹無管人生、OPAT 與健保長照資料串接。", "points": [{"t": 1646, "kind": "數據", "tags": ["健康台灣", "長照3.0"], "text": "台灣從 14% 高齡社會到 20% 超高齡社會只花約 7 年，速度與韓國相近；衛福部推估 2031 年失能人口約 120 萬人，其中約 90 萬為高齡長者。"}, {"t": 1673, "kind": "政策", "tags": ["長照3.0", "復健病房"], "text": "健保署推動復健病房的核心主張：政策要從「照顧失能」轉向「減少失能」，雙管齊下。"}, {"t": 1673, "kind": "數據", "tags": ["財源與預算", "健保給付"], "text": "健保邁入第 31 年，過去 28 年從未達到 5.5% 高推估，但因應超高齡醫療需求與醫事人員出走，總額已連續三年以 5.5% 成長，希望把經費挹注到醫療銜接長照與第一線醫事人員。"}, {"t": 1735, "kind": "數據", "tags": ["健保給付"], "text": "健保大數據顯示醫學中心單純門診比例從約 40% 降到 36%，醫療分級逐步落實，「醫學中心靠輕症賺錢」並非事實。"}, {"t": 1767, "kind": "數據", "tags": ["健保給付"], "text": "全國平均就醫次數因成人健檢、B/C 肝篩檢等而上升，但 65 歲以上長者門診次數沒有上升、甚至略降，「長者沒事逛醫院」的說法不成立。"}, {"t": 1795, "kind": "挑戰", "tags": ["健保給付", "居家醫療"], "text": "長者慢性病共病多，健保資料庫中正在治療的癌症病人約 97 萬人；長者一發燒就容易跑急診，65 歲以上急診就醫上升，又以醫學中心上升最多。"}, {"t": 1852, "kind": "政策", "tags": ["財源與預算", "人力培育"], "text": "今年 9 月 23 日健保總額協商達成共識，各部門均為 5.5% 高推估；明年護理量能約挹注 82.96 億元，另有偏鄉弱勢、在宅安寧、在宅急症、復健病房等多項方案，顯示健保特別針對醫療銜接長照投入資源。"}, {"t": 1910, "kind": "政策", "tags": ["健康台灣"], "text": "健康台灣除癌症防治外推動三高防治「慢性病 888」：8 成三高病人納入健保慢性病照護網（目前已達 64%，一年成長近 5%）、8 成接受生活習慣諮商、8 成達到良好控制。"}, {"t": 1965, "kind": "數據", "tags": ["健康台灣", "復健病房"], "text": "健保署與國衛院合作發表的國家級資料：新診斷糖尿病 10 年後神經病變 18%、心血管 16%、視網膜病變 3.59%，而中風高達 21.39%，約每 5 人就有 1 人中風。"}, {"t": 2022, "kind": "政策", "tags": ["健康台灣", "數位科技"], "text": "生活習慣諮商問卷已完成本土化及信效度驗證，前年 8 月上架健保 APP，共 22 個面向，其中包含「正向社會連結」。"}, {"t": 2127, "kind": "政策", "tags": ["數位科技", "健康台灣"], "text": "與國衛院及六大學會合作推出糖尿病風險分級分流，依個人健保資料客製化回饋風險等級給民眾；今年 3 月與 Google 共同發表結合 AI 與大數據的計畫，5 月 Google 在日內瓦提及此案例。"}, {"t": 2201, "kind": "策略", "tags": ["日本經驗", "復健病房"], "text": "全球平均餘命增加時不健康餘命多半也增加，日本是控制最好的國家，近十年不健康餘命未隨之增加；健保復健病房即瞄準日本復健病房設計。"}, {"t": 2233, "kind": "策略", "tags": ["復健病房", "急性後期照護"], "text": "先以中風為對象，因證據充足；新的神經科學研究顯示黃金復健期不只 3 個月、可到 6 個月，第 4、5 個月積極復健仍能減少失能，觀念已不同於當初 PAC 以 3 個月設計。"}, {"t": 2315, "kind": "政策", "tags": ["在宅急症照護", "居家醫療"], "text": "在宅急症照護並非為解決急診壅塞（其人力需求反而高），而是因應超高齡長者交通與行動不便，把服務送到家；目前以蜂窩性組織炎、泌尿道感染等感染症為主，完成率約九成，相關成果已發表。"}, {"t": 2371, "kind": "政策", "tags": ["在宅急症照護", "財源與預算"], "text": "今年 5 月宣布在宅醫療急症方案；署長回應陳節如理事長，在宅急症及其他在宅方案會依醫院協商、共擬會議等程序陸續再挹注經費。"}, {"t": 2400, "kind": "政策", "tags": ["健保給付", "居家醫療"], "text": "OPAT（門診注射抗生素）讓原需住院者改在門診打抗生素，許多醫院行之有年，現已正式納入給付；台大醫院表示 OPAT 減少約 17% 病房占床率，並成立 OPAT 中心。"}, {"t": 2452, "kind": "政策", "tags": ["復健病房", "日本經驗"], "text": "復健病房籌備已久：陳時中部長任內赴日參訪，疫情前已有兩家醫院先行試辦；署長接棒後再赴日拜會前厚生勞動大臣，了解醫療銜接、人力與藥品韌性規劃。"}, {"t": 2484, "kind": "策略", "tags": ["日本經驗", "復健病房"], "text": "日本小倉復健醫院開辦全日本第一家住院型積極高強度復健模式時，高齡人口約 12%，台灣現已 20%；韓國約 6 年前也跟進，台灣今年開辦，因經費到位、試辦已完成盤點，腳步會更快。"}, {"t": 2510, "kind": "策略", "tags": ["復健病房", "人力培育"], "text": "推出小倉模式復健病房前與各專業學會開過多次會議，明確訂定分工、第一線人力，以及 OT、PT 與病人的比例。"}, {"t": 2563, "kind": "政策", "tags": ["復健病房", "健保給付"], "text": "小倉模式特色是多職類醫事人員共同照護，OT、PT 對病人比例高；為回應護理人力疑慮，支付標準寫入參與醫院須加入住院整合照護（Skill Mix），另有照護經費支撐護理人力，讓家屬不用奔波。"}, {"t": 2592, "kind": "政策", "tags": ["復健病房", "財源與預算"], "text": "復健病房首年挹注 3 億元，今年 9 月開辦；記者會前兩週仍邀護理、居護、OT、PT 等各方做最後一次討論。"}, {"t": 2620, "kind": "政策", "tags": ["復健病房", "健保給付"], "text": "居家模擬情境訓練是重點：職能治療師本來就會做，但需要大空間與時數，多數醫院難以支撐，因此寫入支付標準，要求開辦復健病房者必須設置。"}, {"t": 2647, "kind": "挑戰", "tags": ["急性後期照護", "出院準備"], "text": "現有約 221 家 PAC 醫院提供積極復健，但中風者回家後常見嗆咳、扣扣子困難、忘記患側導致起床跌倒等問題，在傳統急性或亞急性病房容易被忽略。"}, {"t": 2703, "kind": "挑戰", "tags": ["復健病房"], "text": "部分醫院 9 月較晚開張，核心原因是整修居家模擬空間，包括如廁、起身（最易跌倒）、穿衣與進食吞嚥訓練。"}, {"t": 2753, "kind": "數據", "tags": ["復健病房", "財源與預算"], "text": "目前共 10 家醫院開辦復健病房（員郭醫院為啟航記者會承辦醫院），明年另有 26 家的經費；開辦前提是人力與設備完備，由各分區業務組實地確認。"}, {"t": 2781, "kind": "政策", "tags": ["健保給付", "長照3.0"], "text": "「無管人生」吞嚥訓練方案：署長觀察六年來接受訓練人數未大幅成長，核心在支付系統；經與長照司協調經費與業務分工，已於今年 9 月 1 日在高醫小港醫院宣布，設有開辦獎勵、照護獎勵與品質獎勵。"}, {"t": 2896, "kind": "政策", "tags": ["數位科技"], "text": "健保資訊建設：2013 年引進雲端藥歷，2014 年健康存摺上線，2019 年與疾管署整合資料，使台灣在 COVID 期間能掌握國家級診斷、治療與疫苗接種資料。"}, {"t": 3036, "kind": "政策", "tags": ["數位科技"], "text": "健保署與資訊處合作推動醫院端語彙標準化，已公布檢驗項目 LOINC 標準，藥品等其他語彙統一進行中，以利 AI 與大數據分析。"}, {"t": 3059, "kind": "政策", "tags": ["數位科技"], "text": "健保資料庫母法去年完成修法，子法今年 8 月由行政院公告上路，重點包括「目的外使用管理辦法」，規範哪些情況可使用健保資料庫。"}, {"t": 3110, "kind": "政策", "tags": ["醫照整合", "數位科技"], "text": "健保已接收國健署癌症篩檢資料，可看到國家級完整癌症治療歷程；並與長照司串接資料，已取得 A 個管資料，目標是讓醫療與長照第一線人員在資安與隱私前提下互看資料，提供以病人為中心的服務。"}]}, {"id": "3-2", "slot": "09:30–11:20", "title": "復健病房試辦計畫分享", "role": "與談", "speaker": "陳良城 副院長", "org": "臺北市立聯合醫院陽明院區", "orgType": "醫院", "handout": "https://drive.google.com/file/d/1tt-3CRZ0stDfi0uTU8R5NWNyGo-GBbpD/view", "t": 3229, "summary": "陳良城副院長分享臺北市立聯合醫院陽明院區承辦健保復健病房試辦計畫的經過與現況。陽明院區於4月計畫公告後成立統籌小組，7月17日獲公告為首批承辦醫院之一，8月14日收治第一位病人，至11月3日約收治15位中風患者。院區以中西醫整合、營養食療、智慧照護（床墊下光纖感測）、智能復健（AI與雲端機器人）四大特色，搭配生活模擬教室訓練返家能力。他也提出執行困境：後半段一般強度復健時數偏少、65歲以下出院個案無法使用長照3.0資源、年輕個案恢復好會要求提早出院等，盼健保署協調調整。", "points": [{"t": 3292, "kind": "策略", "tags": ["復健病房"], "text": "健保署4月16日公告復健病房試辦計畫後，陽明院區立即成立統籌小組，納入醫師、治療師等專業人員，每週開會追蹤進度。"}, {"t": 3323, "kind": "政策", "tags": ["復健病房", "健保給付"], "text": "申請流程：5月27日遞交計畫書，6月接受書面審查與健保署實地訪查、到台北業務組口頭報告說明人員配置與復健場域，7月17日公告為承辦醫院，計畫期程至116年12月31日。"}, {"t": 3396, "kind": "數據", "tags": ["復健病房"], "text": "8月14日收治第一位病人，統計至11月3日約收治15位，主要從北部醫學中心轉入；男性11位、女性4位，年齡約42至75歲。"}, {"t": 3492, "kind": "策略", "tags": ["復健病房", "出院準備"], "text": "復健病房除了功能恢復，更著重回歸生活的訓練：中風後起床、廚房、浴室等日常動作都要重新學習，才能安全返家、減少失能造成的傷害，這部分對家屬和照顧者也很重要。"}, {"t": 3551, "kind": "策略", "tags": ["復健病房", "數位科技"], "text": "陽明院區盤點現有健保資源與專案，發展四大特色：中西醫整合、營養食療、智慧照護、智能復健。"}, {"t": 3585, "kind": "策略", "tags": ["復健病房", "健保給付"], "text": "中西醫整合：病人入院後會診中醫師，結合健保「西醫住院病人中醫特定疾病輔助醫療計畫」（腦血管疾病、顱腦損傷、脊髓損傷），可做針灸或中藥治療，每週可做五天。"}, {"t": 3659, "kind": "數據", "tags": ["健保給付", "復健病房"], "text": "中醫輔助治療每次病人自付約50元，健保另支付約200多點，經濟負擔不大；中醫師並以舌診儀、脈診儀評估體質後再針灸。"}, {"t": 3716, "kind": "策略", "tags": ["復健病房"], "text": "營養食療：營養師為每位入院病人做個人化營養評估（含BMI、營養供給），並調整餐點，參考MIND飲食增加全穀、低脂、水果與健康油脂。"}, {"t": 3749, "kind": "數據", "tags": ["復健病房"], "text": "營養評估資料顯示熱量與蛋白質攝取達成率約92.6%與94.7%；主要問題為熱量、蛋白質攝取不足，水分攝取不足者約21.4%，高強度復健需要足夠營養支撐。"}, {"t": 3782, "kind": "策略", "tags": ["數位科技", "復健病房"], "text": "智慧照護：中風復健病人容易跌倒，院區在床墊下放置光纖感測薄墊，24小時無感監測心跳、呼吸、離床等狀態，數據即時顯示在護理站。"}, {"t": 3843, "kind": "策略", "tags": ["數位科技", "人力培育"], "text": "智慧床墊可設定警示門檻，數值異常或病人離床時自動通知，護理人員不必時時守在床邊，可減少人力負擔並提升病人安全。"}, {"t": 3896, "kind": "策略", "tags": ["數位科技", "人力培育"], "text": "智能復健：導入AI智慧復能系統，以感測器蒐集數據分析後產生個人化復健處方，再搭配雲端機器人協作訓練肌力與耐力，提升效率並減少部分治療師人力需求。"}, {"t": 3993, "kind": "策略", "tags": ["復健病房", "出院準備"], "text": "院方設有個管師與病人、家屬溝通計畫內容與期待，降低誤解；並於10月1日舉辦記者會、接受多家媒體報導，協助宣導試辦計畫。"}, {"t": 4051, "kind": "策略", "tags": ["復健病房", "出院準備"], "text": "院區有一般復健中心、復健病房，以及另設的「生活模擬教室」，布置客廳、餐廳、廚房、臥室、陽臺等擬真空間，讓病人練習起臥、穿衣、沐浴、煮飯等居家生活。"}, {"t": 4085, "kind": "數據", "tags": ["復健病房"], "text": "影片介紹：腦血管疾病長年位居國人十大死因第四名，平均約每42分鐘就有一人因中風死亡，過去病人常面臨住院一段時間就得被迫轉院的困境。"}, {"t": 4122, "kind": "政策", "tags": ["復健病房", "日本經驗"], "text": "復健病房試辦計畫參考日本小倉復健醫院模式，以具復健潛能的腦中風患者為對象，提供最長180天整合照護與每日高強度訓練，並模擬居家環境協助銜接返家。"}, {"t": 4152, "kind": "政策", "tags": ["復健病房", "急性後期照護"], "text": "計畫以地區、區域醫院為主要場域，床數不得少於30床並優先設於急性後期照護病房，物理或職能治療師與病人比為1比8，已於7月上路；與現行PAC不同在於更積極的高強度復健，被形容為「復健補習班」。"}, {"t": 4184, "kind": "政策", "tags": ["復健病房", "財源與預算"], "text": "影片中署長說明，今年另外編列護理費約21億元，未來四年希望達到約100億元規模；第一批試辦全臺共10家醫院參與。"}, {"t": 4280, "kind": "挑戰", "tags": ["急性後期照護", "家庭照顧者"], "text": "受訪家屬表示，過去中風後六個月內需不斷轉院排床，每兩三週就換一次醫院，造成很大的焦慮與心理負擔；180天的試辦計畫讓治療得以延續。"}, {"t": 4343, "kind": "策略", "tags": ["復健病房", "家庭照顧者"], "text": "治療師在模擬空間指導病人用健側手搭配剪刀等方式完成備餐，也教家屬如何安全省力地協助上下輪椅、起身，確認病人能獨立操作後才安排出院。"}, {"t": 4411, "kind": "挑戰", "tags": ["復健病房", "健保給付"], "text": "計畫分前後兩段：前半段高強度復健每天約3小時，後半段一般復健約1.5小時；民眾對兩種強度有疑義，擔心後半段時數少、配合度下降，已向署長反映，盼未來修訂時調整。"}, {"t": 4476, "kind": "挑戰", "tags": ["復健病房"], "text": "等待入院的作業時間約3至5天，主要是調整床位與男女床限制；目前申請30床尚未額滿，若床滿則需等有人出院才能入住。"}, {"t": 4502, "kind": "挑戰", "tags": ["長照3.0", "復健病房"], "text": "長照3.0放寬讓PAC身分結案的病人可使用長照資源，但復健病房試辦計畫出院個案在健保資料中不屬PAC身分，65歲以下者完全無法使用接送、陪同就醫、家事服務、居家復健等長照服務。"}, {"t": 4560, "kind": "建議", "tags": ["長照3.0", "跨部會協作"], "text": "陳副院長請署長協助與長照主管機關協調，讓復健病房出院個案也能銜接長照資源，避免病人覺得住了復健病房反而失去權益。"}, {"t": 4590, "kind": "挑戰", "tags": ["復健病房"], "text": "年輕或恢復良好的個案常住不到六個月就主動要求提早出院；但保留可住到六個月的選擇，能讓病人有緩衝時間、壓力較小。"}]}, {"id": "3-3", "slot": "09:30–11:20", "title": "全民健康保險復健病房試辦計畫", "role": "與談", "speaker": "陳靖倫 主任", "org": "桃園長庚紀念醫院復健科", "orgType": "醫院", "handout": "https://drive.google.com/file/d/1dtwxiK7GHgxcbnM3tJ3iDFST1QqwzWnR/view", "t": 4621, "summary": "陳靖倫主任分享桃園長庚紀念醫院從腦中風PAC走向復健病房試辦計畫的經驗。桃園長庚自103年起承辦PAC，有220床復健病床，規劃40床投入試辦，並以既有職能治療空間打造副木室與模擬浴廁、餐廚、臥室的居家訓練區。9月至10月收案27人，初步評估顯示BI、BBS、FMA、6分鐘行走距離與營養指標都明顯進步，趨勢與過去十年PAC資料一致。他代職能治療師爭取合理給付：副木製作應給治療費、新增日常生活訓練職能治療項目，會診與處置費不應內含，並希望過年返家不喪失試辦身分。", "points": [{"t": 4644, "kind": "策略", "tags": ["復健病房", "急性後期照護"], "text": "桃園長庚不是新設病房，而是從原有PAC與傳統復健病房轉型，在既有多床的復健病房中規劃40床投入試辦計畫，經營模式與新設單位不同。"}, {"t": 4724, "kind": "政策", "tags": ["復健病房", "日本經驗"], "text": "推動復健病房的背景：台灣進入超高齡社會，急性醫療與長照之間有轉銜缺口，因此參考日本回復期復健病棟制度、延續PAC經驗，建立從急性期到社區的連續照護模式。"}, {"t": 4762, "kind": "數據", "tags": ["急性後期照護"], "text": "桃園長庚自103年4月承辦腦中風PAC，每季收案約10至30人，每年總案量最多約60多人；另承接脆弱性骨折、衰弱高齡、創傷性神經損傷等PAC類別。"}, {"t": 4795, "kind": "數據", "tags": ["復健病房"], "text": "試辦計畫9月1日至10月31日收案27人，其中6人成功返家結案、21人仍住院；結案者住院天數約9至36天，部分病人恢復很快。"}, {"t": 4836, "kind": "挑戰", "tags": ["復健病房", "人力培育"], "text": "全院220床復健病床中約180床為慢性一般復健病床，收治不符PAC條件的重度中風、頭部外傷、脊髓損傷等病人；高強度復健之外，仍需人力照顧這些傳統復健病人。"}, {"t": 4906, "kind": "策略", "tags": ["復健病房"], "text": "試辦病房集中在同一區，與一般復健病人區隔；治療空間寬敞明亮，並趁此機會更新設備，強化職能治療區內的居家模擬訓練室。"}, {"t": 4986, "kind": "策略", "tags": ["復健病房"], "text": "職能治療區設有副木（輔具）室，由專門的治療師依病人狀況量身製作副木；另有個別評估室與個別治療室，可做額外評估與紀錄。"}, {"t": 5027, "kind": "策略", "tags": ["復健病房", "出院準備"], "text": "日常生活訓練區模擬浴廁（升降馬桶、洗澡設施、進出浴缸）、餐廚（改良式餐具、微波爐、瓦斯爐、水槽）與臥室（床與輪椅移位、穿襪、撿物輔具），納入ADL訓練課程。"}, {"t": 5094, "kind": "策略", "tags": ["復健病房", "人力培育"], "text": "物理治療部分運作順利：治療人力10人，優先配置4人分兩個時段服務試辦病人，一天可達35人次，目標住院後3至5天內開始物理治療，並定期召開跨專業會議；重點挑戰在職能治療。"}, {"t": 5130, "kind": "數據", "tags": ["復健病房"], "text": "初步分析：Barthel日常生活功能（BI）平均由46.73分升至77分，mRS失能程度由3.85降至3.17，顯示自理能力明顯改善。"}, {"t": 5167, "kind": "數據", "tags": ["復健病房"], "text": "平衡（BBS）由33.12升至54分、感覺動作（FMA）由51.68升至61.6分，6分鐘行走距離由約256公尺增至346公尺，走5公尺所需秒數由14.53秒降至5.3秒，步態與心肺耐力進步最明顯。"}, {"t": 5199, "kind": "數據", "tags": ["復健病房", "急性後期照護"], "text": "這些趨勢與桃園長庚連續約十年、400多筆PAC資料相似，顯示只要篩選出合適病人並給予高強度復健，就能達到一致的效果；但目前個案數少，結評樣本偏少，宜看方向性。"}, {"t": 5233, "kind": "數據", "tags": ["復健病房"], "text": "這類病人較少需要語言治療，吞嚥功能（FOIS）全程維持7分滿分；營養（MNA）由9.23升至11.4，生活品質指標也呈改善。"}, {"t": 5307, "kind": "策略", "tags": ["復健病房"], "text": "陳主任肯定試辦計畫是德政：把mRS 3至4分、積極復健有效的病人挑出來，讓他們有機會快速恢復返家，具社會意義。"}, {"t": 5343, "kind": "挑戰", "tags": ["健保給付", "復健病房"], "text": "副木給付不合理：一般病人申報副木含製作費與材料費，但PAC與復健病房病人只給材料費、不給治療費；治療師提供相同服務卻拿到較低點值，等於變相降低給付。"}, {"t": 5383, "kind": "建議", "tags": ["健保給付", "人力培育"], "text": "建議副木的材料費與治療費一併包裹給付，在「其他費用」中合理反映職能治療師量身製作副木的專業付出。"}, {"t": 5424, "kind": "建議", "tags": ["健保給付", "人力培育"], "text": "複雜職能治療（43029A）成人給付600點多年未調整；試辦病房雖採包裹給付，私立醫院內部分配仍比照43029A。建議新增「日常生活訓練職能治療」給付項目並提高點值，申報須包含日常生活訓練。"}, {"t": 5467, "kind": "建議", "tags": ["健保給付", "復健病房"], "text": "建議住院會診費與相關處置檢查費（如牙科處置、精神科評估）不要內含於住院模式費用，應可另外申報；目前健保署認定可核實申報的處置僅限支付標準特定章節，盼總署釋疑。"}, {"t": 5534, "kind": "建議", "tags": ["復健病房", "健保給付"], "text": "桃園長庚多年慣例是過年讓病人返家、病房趁機整修，醫護也能休息；但依規定一旦出院就喪失試辦身分。建議允許過年短暫返家後回院銜接，仍保有復健病房試辦身分，提升滿意度。"}]}, {"id": "3-4", "slot": "09:30–11:20", "title": "台中醫院復健病房經驗", "role": "與談", "speaker": "蔡明妙 主任", "org": "衛福部臺中醫院復健科", "orgType": "醫院", "handout": "https://drive.google.com/file/d/1g_evxMV7Sgr3L8TCczwrBCC6Tt82HnCx/view", "t": 5633, "summary": "蔡明妙主任分享衛福部臺中醫院從中期照護、腦中風PAC到112年全國第一家前瞻復健病房，再到現行健保復健病房試辦計畫的十多年經驗。臺中醫院以全責照護（白天1比3、晚上1比6）、42床全功能一站式病房、居家模擬與返家「畢業考」、家屬賦能、出院前兩週跨專業出院準備會議為特色，並與中部三大醫學中心建立轉銜綠色通道。7月24日起收案，結案者幾乎全數返家，平均住院約30.7天，管路移除率高。她指出65歲以下出院者無法使用長照、中風年輕化，以及照護比過高恐影響密集訓練等問題。", "points": [{"t": 5660, "kind": "數據", "tags": ["復健病房"], "text": "臺中醫院7月24日收第一位病人，統計至演講前的週五共收案57人、結案29人，部分因肺炎等提早結束；完成計畫的病人約96%成功返家，僅一位獨居、家人在外地者轉入機構。"}, {"t": 5703, "kind": "策略", "tags": ["急性後期照護", "復健病房"], "text": "臺中醫院一路從中期照護走到復健病房：100年8月由時任院長李孟智成立中期照護工作小組並帶隊赴美參訪亞急性照護機構，102年成立衛福部委託的全國第一家中期照護病房。"}, {"t": 5776, "kind": "數據", "tags": ["急性後期照護"], "text": "中期照護在台灣的起點更早：94年老年醫學會推動社區醫院轉型；96年臺北榮總將急性期後功能退化病人轉往退輔會體系住院約42天，一年後追蹤死亡率降低約62%。"}, {"t": 5883, "kind": "政策", "tags": ["急性後期照護", "健保給付"], "text": "臺中醫院103年接健保署PAC計畫，與臺中三大醫學中心合作；105年PAC擴大到骨折、腦傷、衰弱、燒燙傷等對象。"}, {"t": 5918, "kind": "政策", "tags": ["復健病房", "日本經驗"], "text": "108年時任醫事司司長、現任石部長帶隊赴日本小倉、熊本等復健醫院參訪，回國後撰寫「因應人口老化復健醫療試辦計畫」，因疫情延後，最後於112年由臺中醫院（都會型）與朴子醫院（鄉村型）試辦。"}, {"t": 5987, "kind": "策略", "tags": ["復健病房", "家庭照顧者"], "text": "112年臺中醫院把整層病房改造為前瞻復健病房，最大變化是導入全責照護：白天照服員1比3、晚上1比6，因為病人白天要針灸、復健、運動、洗澡，上下奔波，1比3已相當吃力，至今仍維持此比例。"}, {"t": 6065, "kind": "策略", "tags": ["出院準備", "復健病房"], "text": "前瞻復健病房另導入居家環境模擬、跨專業出院準備會議、每位病人一本客製化出院衛教本，以及出院後追蹤長照使用情形三個月。"}, {"t": 6133, "kind": "數據", "tags": ["復健病房", "家庭照顧者"], "text": "112年試辦計畫收案282位，其中155位為腦中風，約52%選用全責照護；當時有計畫補助，病人一天只需自付600多元，現在沒有補助要1600多元，仍比住院整合照顧計畫高。"}, {"t": 6174, "kind": "數據", "tags": ["復健病房", "急性後期照護"], "text": "112年計畫已將住院天數由PAC的12週延長至180天，但155位中風病人中真正住超過84天的只有16位、不到一成；延長天數可照顧到病況較重的病人。"}, {"t": 6207, "kind": "數據", "tags": ["急性後期照護"], "text": "臺中醫院從中期照護至去年底累計收案約2000位，其中腦中風1300多位，收案量曾占中彰投地區約30.4%。"}, {"t": 6245, "kind": "策略", "tags": ["醫照整合", "急性後期照護"], "text": "跨院轉銜採綠色通道、單一窗口：中國醫藥大學附設醫院等醫學中心個管師在急性住院前幾天就評估病人潛能，提早預約床位，讓病人在預定日期轉入；每半年與上游醫院開會檢討轉銜。"}, {"t": 6309, "kind": "策略", "tags": ["醫照整合", "復健病房"], "text": "院內整合：中風與骨折病人住院第一天就通報整合系統、三日內啟動，復健科醫師與治療師評估是否適合轉復健病房；選擇全責照護的弱勢病人不論有無管路一律收治，轉銜成功率100%。"}, {"t": 6342, "kind": "策略", "tags": ["醫照整合"], "text": "首創急慢性共照：病人轉到復健科後，骨科醫師一週後、神經內科兩週後會再回來看病人，照護不中斷。"}, {"t": 6376, "kind": "策略", "tags": ["復健病房"], "text": "復健病房共42床，多為兩人房，設於長照大樓四樓；病室、物理、職能、語言治療室與ADL、烹調、居家模擬等功能訓練區全部集中在同一平面，避免病房與治療室分處不同樓層、往返耗時。"}, {"t": 6444, "kind": "策略", "tags": ["復健病房"], "text": "護理站刻意設在治療區與功能訓練區之間，病人在治療時間以外自主練習或烹調訓練時，護理師與醫師都看得到，提升安全；PT、OT、ST治療室相通，治療師容易彼此了解治療內容。"}, {"t": 6544, "kind": "策略", "tags": ["復健病房", "家庭照顧者"], "text": "規定每日復健2至5小時，臺中醫院實際至少3小時，加上語言治療、針灸與自主訓練，病人每天活動常超過5小時；治療師另訂個別化床邊運動計畫上傳護理系統，由照服員陪同、護理師監督執行。"}, {"t": 6612, "kind": "策略", "tags": ["復健病房", "醫照整合"], "text": "病人入住一週內召開團隊會議，醫師、治療師、營養師、藥師、社工、出院準備人員都須事先完成評估；營養師著重蛋白質攝取，112年蛋白質攝取量達80%以上者約95.8%。"}, {"t": 6676, "kind": "策略", "tags": ["復健病房"], "text": "藥師介入處理多重用藥，提供客製化用藥清單並檢視交互作用，當時平均每五顆藥可減掉一顆。"}, {"t": 6712, "kind": "策略", "tags": ["出院準備", "復健病房"], "text": "居家模擬室使用可移動家具，依病人家中照片或影片、偏癱側別，擺成安全省力的配置給病人練習，建議回家照著調整；衛浴刻意做成一般家庭大小，示範加裝扶手、調整蓮蓬頭等可行改造。"}, {"t": 6776, "kind": "策略", "tags": ["出院準備", "復健病房"], "text": "返家前有「畢業考」：PT考核居家動線（如沙發到廁所到臥室）、OT考核吃飯穿衣洗澡等日常任務，未通過就加強訓練，確認有能力才出院。"}, {"t": 6838, "kind": "策略", "tags": ["家庭照顧者", "出院準備"], "text": "以家屬賦能學習檢核表，出院前教家屬翻身、移位、上下樓梯、協助洗澡、上下車等技巧；112年參與的家屬超過一半。"}, {"t": 6868, "kind": "策略", "tags": ["人力培育", "家庭照顧者"], "text": "分級全責照護：依病人功能與照顧困難度分組，動態調整照服員負荷，並把同一照服員負責的病人集中在相鄰病房；也向病人說明國外復健病房是團隊照顧，不是固定一對一。"}, {"t": 6933, "kind": "策略", "tags": ["人力培育", "復健病房"], "text": "照服員到職先評估與訓練安全移位、灌食等能力，並明訂工作職責與考核表，由護理師每日稽核是否帶病人做治療師開的運動，避免一對三的病人比一對一的病人更常躺著沒事做。"}, {"t": 6998, "kind": "策略", "tags": ["出院準備", "長照3.0"], "text": "出院前兩週召開跨專業出院準備會議，治療師、營養師、藥師、醫師與家屬一起說明病程、回家後復健、用藥與飲食，並確認長照與社會資源需求，提供客製化居家指引；成效好但相當耗費人力。"}, {"t": 7056, "kind": "數據", "tags": ["復健病房"], "text": "統計7月24日至10月20日收案45人、結案17人（含4人病情變化提早結案）；因事先約好轉入日期，等待天數約1至10天，盡量讓急性醫院不必壓床。"}, {"t": 7091, "kind": "數據", "tags": ["復健病房"], "text": "結案13人平均住院約30.7天，目前57位收案中只有一位申請延長超過12週；病人準備好就出院。入院時多數無法行走，出院時已全部能持輔具或不用輔具行走。"}, {"t": 7125, "kind": "數據", "tags": ["復健病房", "出院準備"], "text": "出院一個月後電訪13人：7人日常生活完全獨立、不需輔具即可行走，5人仍需輔具並持續門診復健，1人聯繫不上。"}, {"t": 7159, "kind": "數據", "tags": ["復健病房"], "text": "不論有無管路都收治；入院時有鼻胃管10人、尿管4人，鼻胃管平均約22天移除，報告時最後一位也已移除，管路移除率與返家率皆達100%。"}, {"t": 7196, "kind": "挑戰", "tags": ["長照3.0", "復健病房"], "text": "13位結案者中8人成功申請長照（交通接送、居家服務等），另5人因未滿65歲且無身心障礙手冊不符資格，與陽明院區遇到相同困境，盼調整65歲以下病人的長照使用規定。"}, {"t": 7232, "kind": "挑戰", "tags": ["復健病房"], "text": "中風年輕化嚴重：17位結案者有8位未滿65歲，病房現有三十多位病人中有3位三十幾歲，多是長期高血壓、糖尿病到中風後才發現，危險因子多為肥胖。"}, {"t": 7270, "kind": "挑戰", "tags": ["復健病房", "人力培育"], "text": "全責照護雖減輕經濟負擔，但長期是否比一對一看護進步少仍待觀察；若結合住院整合照護計畫採1比6、1比7照護比，病人難以頻繁下床密集訓練，蔡主任認為並不理想。"}]}, {"id": "3-5", "slot": "09:30–11:20", "title": "復健病房試辦計畫分享", "role": "與談", "speaker": "郭鐘添 院長", "org": "員郭醫院", "orgType": "醫院", "handout": "https://drive.google.com/file/d/1wX7dM6miU15UWO5bICk5a9tGfq83TwtF/view", "t": 7332, "summary": "彰化員林員郭醫院郭鐘添院長分享地區醫院參與健保復健病房試辦的經驗。員郭做 PAC 多年，發現病人在醫院練得好、回家卻不知所措，因此在醫院對面「員郭未來室」2 樓打造「賦健基地」ADL 情境訓練空間，並設計「生活功能解鎖護照」，把食衣住行育樂拆成約 150 項任務，以銅銀金盃與白金牌遊戲化激勵，延伸到田地採收、全聯購物、公園等社區情境。院長也建議發展認證的功能型照服員、減輕家屬看護負擔、開放替代役醫事人員到地區醫院。", "points": [{"t": 7385, "kind": "策略", "tags": ["急性後期照護", "復健病房"], "text": "員郭醫院已做 PAC 約六到八年，住院病人在一般病房，高強度復健集中在 2 樓執行，PAC 是加入復健病房試辦的基礎。"}, {"t": 7425, "kind": "數據", "tags": ["急性後期照護"], "text": "員郭 PAC 收案人數從 2023 年約 100 人，成長到 2025 年約 308 人，今年至演講時已超過去年。"}, {"t": 7469, "kind": "挑戰", "tags": ["復健病房", "出院準備"], "text": "PAC 病人缺少「回家練習」，在醫院一切順利，返家後卻出現許多困難，這是員郭加入復健病房試辦計畫、想補上的缺口。"}, {"t": 7553, "kind": "數據", "tags": ["復健病房"], "text": "截至 10 月 30 日復健病房收案 40 位、結案 4 位（演講時約 6 位）、34 位持續復健；2 位因 A 型流感或肺炎提早出院，另有 1 位因腎臟問題轉院。已出院個案平均住院約 44 天。"}, {"t": 7594, "kind": "策略", "tags": ["復健病房", "社區醫療"], "text": "地區醫院的病人多由彰基、員基及中部大型醫院下轉，PAC 與復健病房制度讓地區醫院在垂直整合中有明確角色，並向下連結病人與社區。"}, {"t": 7714, "kind": "策略", "tags": ["復健病房", "醫照整合"], "text": "要讓上游醫院願意轉介，關鍵是建立信任：平常與上游團隊開會，轉下來的病人要照顧好讓對方安心；上游醫師也會到員郭看自己的病人，病人可延續原本用藥、共同照顧。郭院長認為這可作為地區醫院可複製的模式。"}, {"t": 7820, "kind": "策略", "tags": ["復健病房", "出院準備"], "text": "在醫院對面的「員郭未來室」2 樓打造「賦健基地」，除了智慧化設備提升體能，也設 ADL 生活功能情境教室；理念是「生活可以是復健，但復健不能是全部生活」，呼應陳署長「復健補習班」的說法。"}, {"t": 7901, "kind": "策略", "tags": ["復健病房"], "text": "賦健基地從門口就開始訓練：用鑰匙開門、洗衣晾衣，甚至設有拜拜的角落；達成目標者可上「白金英雄榜」。新設備引進後，治療團隊也需另外培訓。"}, {"t": 7938, "kind": "策略", "tags": ["復健病房"], "text": "設計洗手、梳頭、吃飯等「任務卡」，讓枯燥的復健變得有趣，讓病人在取得成就感的過程中不知不覺恢復功能。"}, {"t": 7983, "kind": "策略", "tags": ["復健病房"], "text": "推出「生活功能解鎖護照」，病人與家屬討論後寫下自己的目標與復健旅程；賴總統參訪時簽下第一本護照。"}, {"t": 8113, "kind": "策略", "tags": ["復健病房"], "text": "護照把任務分成食衣住行育樂六大生活領域，分級獎勵：以「吃」為例，自己吃飯得銅盃，能站著備餐得銀盃，能到田地採菜或到全聯採買再回來自己煮得金盃，藉此練習參與社會。"}, {"t": 8305, "kind": "策略", "tags": ["復健病房", "社區醫療"], "text": "醫院旁整理出「大田地」「小田地」，讓病人練習翻土、種植、澆水、採收秋葵；也帶病人練習使用販賣機、走到公園野餐玩遊戲，從走出醫院到踏入社區。"}, {"t": 8381, "kind": "數據", "tags": ["復健病房"], "text": "六大領域各約 25 項、共約 150 項任務，完成 120 項以上可獲白金牌，代表大致可以回家；成果以雷達圖呈現，護照前後貼上入院與畢業照片。"}, {"t": 8768, "kind": "策略", "tags": ["復健病房", "出院準備"], "text": "成功案例阿娥姐：中風前在夜市賣地瓜球，目標是重回市場。從輪椅開始高強度訓練，返家前啟動賦健基地模式，練穿衣、備餐、洗衣、過馬路，到對面服飾店買衣服結帳、到全聯買蛋、採秋葵，最後煮秋葵炒蛋請團隊吃後「畢業」，共解鎖 126 項任務、登上白金英雄榜。"}, {"t": 9008, "kind": "數據", "tags": ["復健病房"], "text": "目前病人在高強度復健後、返家前約用兩到三週在賦健基地強化，院內仍在討論最適天數；任務平均達成率約六到七成，使用量從 9 月到 11 月明顯增加。"}, {"t": 9120, "kind": "挑戰", "tags": ["復健病房", "數位科技"], "text": "實務上兩大困難：院內跨專業資訊整合不足（各職類各自記錄，團隊會議時成員散在各處），以及病人需要真正的個別化照顧計畫。"}, {"t": 9156, "kind": "策略", "tags": ["數位科技", "復健病房"], "text": "與資訊廠商（昕力資訊）開發個別化照護系統：串接護理建檔與 OT、營養師等跨專業紀錄，讓分散各地的成員都能看到同一份資料，並以醫病共享決策（SDM）讓病人與家屬參與擬定短、中期計畫。"}, {"t": 9325, "kind": "策略", "tags": ["復健病房"], "text": "設計 28 張「願望圖卡」，病人與家屬可勾選（也能自行新增）想完成的事，治療師再把願望拆解成多項任務與治療計畫，系統以雷達圖呈現食衣住行育樂進展並產出統計，預計明年完成。"}, {"t": 9444, "kind": "建議", "tags": ["人力培育", "復健病房"], "text": "治療師人力吃緊，郭院長建議發展「功能型照服員」，讓願意配合的照服員納入團隊協助功能訓練；並希望政府辦理訓練與證書，使其能力延伸到口腔照護、足部照護與復健照護，尤其是已有六年以上經驗的資深照服員。"}, {"t": 9475, "kind": "挑戰", "tags": ["家庭照顧者", "復健病房"], "text": "家屬多請一對一看護，一天約 3,000 元、一個月約 9 萬元，負擔沉重；雖有住院整合照護計畫，但最大問題是找不到人，院長提出是否能有外籍照護人力的機會。"}, {"t": 9508, "kind": "建議", "tags": ["人力培育", "社區醫療"], "text": "替代役醫師可到彰化老人福利機構服務，卻不能到醫院；郭院長建議開放替代役醫師及醫事人員到地區醫院服務三到六個月，讓年輕醫事人員了解地區醫院在做什麼，也補充人力。"}]}, {"id": "3-6", "slot": "11:20–12:00", "title": "上午綜合座談", "role": "座談", "speaker": "", "org": "", "orgType": "", "t": 10044, "summary": "上午綜合座談由馬海霞副理事長主持，聚焦復健病房試辦計畫。提問涵蓋增稠劑公費化與坐姿餵食、功能型照服員能否投入高強度復健、居家模擬訓練的人力配置、出院後銜接長照，以及治療費多年未調整。陳亮妤署長回應：銜接長照與第 4–6 個月支付問題，預計 12 月共擬會變更；人力比 1:8、每日 2–5 小時是專家最大公約數，將滾動檢討；支付調整不等於第一線加薪，治療師人力需各職類凝聚共識，並以早療開放兼任為例。", "points": [{"t": 10136, "kind": "策略", "tags": ["復健病房", "出院準備"], "text": "馬海霞副理事長開場：期待復健病房讓病人一開始就知道未來方向（回家生活或重返就業），一進 PAC／復健病房就依此規劃復健。"}, {"t": 10290, "kind": "建議", "tags": ["健保給付", "財源與預算"], "text": "曾在日本佐久大學辦理台灣長照人才培訓的王姓提問者指出，拔管後增稠劑需自費、健保不給付，低收入戶與居服員多不會使用，易造成嗆咳，建議增稠劑改由公費支應；另質疑台灣餵食多站著餵，應推廣坐姿協助進食。（現場未直接回應）"}, {"t": 10478, "kind": "挑戰", "tags": ["人力培育", "復健病房"], "text": "台灣長期照顧物理治療學會林理事長提醒：PAC 屬高強度復健且禁忌症多，若由照服員執行須明確界定職責；長照賦能階段（約六個月後）的照服員分流則表示贊同並願意協助培訓。"}, {"t": 10572, "kind": "建議", "tags": ["人力培育", "復健病房"], "text": "林理事長的人力建議：檢討復健病房治療師配置與合理工作量、改善薪資；參考國際 PT/OT assistant 制度，讓未考取執照者在治療師指導下協助治療；導入智慧自動化輔具；訓練病房護理人員協助早期復健、減少治療師非專業工作；建立依疾病與功能分級的制度及人力保障、品質監測。"}, {"t": 10747, "kind": "建議", "tags": ["復健病房", "長照3.0"], "text": "一位臺大教授以美國經驗肯定居家模擬與外出訓練，詢問居家模擬空間的使用率與人力配置；並建議出院後與長照賦能銜接，照服員依治療計畫協助。成效指標也應納入 IADL、認知、社會參與與家屬照護能力，不只看行動與 BADL。"}, {"t": 10911, "kind": "挑戰", "tags": ["健保給付", "復健病房"], "text": "臺大教授呼應陳靖倫主任的倡議：復健治療支付自民國 86 年以來近 30 年未調整，要提供高品質服務，支付標準需重新檢討。"}, {"t": 10966, "kind": "政策", "tags": ["復健病房", "長照3.0"], "text": "陳亮妤署長回應：銜接長照原本已設計在復健病房方案中，送衛福部後因專家意見被刪除；試辦後多方反映，健保署共擬會每三個月一次，預計 12 月提會變更，健保署可直接解決。"}, {"t": 11031, "kind": "政策", "tags": ["復健病房", "健保給付"], "text": "陳署長：復健病房定位是「積極住院型復健」（復健補習班），因 PAC 強度不足而設，不只是延長住院時間。另有反映第 4–6 個月支付偏低、家屬要求提早出院，也將在 12 月共擬會修改支付。"}, {"t": 11084, "kind": "政策", "tags": ["健保給付", "人力培育"], "text": "陳署長：人力是醫院最大難題，各職類皆缺。總額擴增後，醫事人員診察費已於 10 月 8 日宣布調升，護理人員明年也有額外經費挹注；治療師支付調整，請復健醫學會、物理治療與職能治療等團體先凝聚共識，一起到健保署討論。"}, {"t": 11143, "kind": "政策", "tags": ["健保給付", "人力培育"], "text": "陳署長坦言：調健保支付不一定等於第一線加薪，各醫院分配制度不同（連夜班費都不一樣），支付與個別治療師薪資的連結需更細緻討論；但健保整體朝擴大健康投資、照顧第一線人員方向走。"}, {"t": 11197, "kind": "政策", "tags": ["復健病房", "日本經驗"], "text": "陳署長說明人力比與時數：日本為 1:4、每日 3–5 小時，台灣訂 1:8、每日 2–5 小時，是考量醫院經營、病人負荷後專家與學協會的最大公約數；試辦計畫將以開放心態滾動檢討。"}, {"t": 11279, "kind": "策略", "tags": ["人力培育", "復健病房"], "text": "郭鐘添院長澄清：功能型照服員不是用在前段高強度復健，而是後段準備返家時，協助帶病人到全聯、田地等外出訓練，因家屬不一定能陪同。"}, {"t": 11368, "kind": "建議", "tags": ["人力培育"], "text": "陳良城副院長補充：物理治療師養成需四到六年，但國考及格率偏低、投資報酬受質疑，建議物理治療專業團體從內部檢討考照制度的彈性，以紓解人力短缺。"}, {"t": 11477, "kind": "策略", "tags": ["復健病房", "人力培育"], "text": "一位復健科主任回應：照服員初到復健病房，治療師與護理師會先評估並給予基本訓練，只執行團隊確認可做的事（如依計畫陪練走），不是取代治療師；功能訓練主要仍在治療室進行每日 2–5 小時，居家模擬室只在移位、刷牙、洗澡等特定階段使用。"}, {"t": 11574, "kind": "數據", "tags": ["健保給付", "復健病房"], "text": "主任補充給付面：PAC 後段已提高給付、75 歲以上再加一級；原 PAC 病房內的檢查、處置、給藥沒有另外給付，復健病房計畫則另行支付。但支付增加不代表治療師薪水增加，取決於醫院營運與績效制度。"}, {"t": 11611, "kind": "建議", "tags": ["人力培育"], "text": "另有與談人指出，物理治療師法保障專業執行範圍，醫院可界定輔助型照服員以陪伴等不涉及物理治療專業的工作為主，仍能分擔不少人力。"}, {"t": 11674, "kind": "政策", "tags": ["重症兒童", "人力培育"], "text": "陳署長以早療為例：健保今年擴大以家庭為中心的早療論質計酬方案，錢已備好卻卡在人力；她親自主持三次會議說服專業團體，已宣布團隊中的臨床心理師、物理治療師、職能治療師可開放兼任，否則許多孩子接受不到服務。"}, {"t": 11765, "kind": "政策", "tags": ["人力培育", "財源與預算"], "text": "陳署長：台灣從高齡（14%）到超高齡（20%）只花 7 年，專業人力需求只會增加，未來預算一定支持，給付也會寫明一定比例回饋第一線人員；但人力政策分屬長照司、醫事司、護理及健康照護司，各職類哪些可開放、哪些須維持品質，需凝聚共識、以台灣最大利益前進。"}, {"t": 11882, "kind": "策略", "tags": ["人力培育", "出院準備"], "text": "馬海霞副理事長分享陽光基金會重建中心如同「社福界的 PAC」：燒傷傷友入住時先共同討論期待與興趣，訂定個別化計畫（返回職場或居家）；由受政府訓練認可的照服員、居服員在專業指導下協助訓練活動（非治療），並提供工作能力強化訓練。"}, {"t": 12018, "kind": "建議", "tags": ["人力培育", "社區醫療"], "text": "林理事長第二次發言：功能型照服員較接近長照賦能，可配合照服員能力分流討論；年輕治療師偏好兼任，建議醫院與已達六百多家的物理治療所等合作兼任，也讓結案後仍需復健的個案轉往治療所；考照放寬已與考試院、考選部討論中。"}]}, {"id": "4-0", "slot": "13:00", "title": "主題：台灣醫療照顧需求重症兒童的現況與展望", "role": "主持", "speaker": "孫一信 秘書長", "org": "台灣社會福利總盟", "orgType": "主辦單位", "t": 15540, "summary": "孫一信秘書長主持下午「台灣醫療照顧需求重症兒童的現況與展望」場次。他指出醫療依賴重症兒人數雖少，卻是長期較少被關注、極難處理的議題，對孩子與家庭造成沉重負擔，因此特別安排兩個半小時討論。場次由台大兒童胸腔加護科呂立主任主講，再由楊千慧醫師介紹日本經驗、楊玲玲秘書長分享日本參訪與台灣做法、聯醫黃啟南主任分享以PAC方式照顧醫療依賴重症兒的童羽之家經驗。", "points": [{"t": 15583, "kind": "挑戰", "tags": ["重症兒童", "家庭照顧者"], "text": "孫秘書長開場指出，醫療依賴重症兒過去較少被關注，人數不多卻非常難處理，對孩子與家庭是很沉重的負擔，所以下午用兩個半小時專題討論。"}, {"t": 15635, "kind": "策略", "tags": ["重症兒童"], "text": "主講人呂立醫師為台大兒童胸腔加護科主任、台大醫學院教授，也是台灣重症兒360發展協會理事長；與談人包括楊千慧醫師、楊玲玲秘書長、黃啟南主任。"}, {"t": 15677, "kind": "策略", "tags": ["日本經驗", "居家醫療"], "text": "楊千慧醫師2017年起投入居家醫療與長照，曾獲日本勇美記念財團補助赴日調查研究並在青空會研修；協會今年8月赴日參訪，也獲青空會前田醫師協助。"}, {"t": 15758, "kind": "策略", "tags": ["重症兒童", "就學與教育"], "text": "楊玲玲秘書長兼具護理師與呼吸治療師背景，為好康居家呼吸照護所負責人，將分享協會在日本看到的經驗及台灣可以怎麼做。"}, {"t": 15794, "kind": "策略", "tags": ["重症兒童", "急性後期照護"], "text": "黃啟南主任在聯醫和平婦幼院區以機構成立「童羽之家」，用PAC（急性後期照護）方式收住醫療依賴重症兒，住期可從數月到半年。"}]}, {"id": "4-1", "slot": "13:00–15:30", "title": "台灣醫療照顧需求重症兒童的現況與展望", "role": "主講", "speaker": "呂立 理事長", "org": "台灣重症兒360發展協會", "orgType": "社福團體", "handout": "https://drive.google.com/file/d/16AqstuiXY_K772X2NzDBBW1NiNe9cHv5/view", "t": 15836, "summary": "呂立理事長指出孩子救回後「出院能去哪裡」是最大問題。醫療照顧重症兒同時是兒童與身障者，需長期使用呼吸器、氣切、管灌等維生設備，但居家醫療、早療、身障福利、長照、特教五套制度各自為政，重擔落在24小時不停歇的家長身上。她說明健保兒童訪視加成、低出生體重兒計畫等進展，也點出抽痰法規模糊、長照與早療拒收、就學門檻等缺口；協會已自行推出定義與培訓課程，並訴求建立專責諮詢個管中心、定義與統計，參考日本立法，跨部會整合。", "points": [{"t": 15876, "kind": "挑戰", "tags": ["重症兒童", "出院準備"], "text": "呂理事長說，加護病房好不容易救回的孩子出院後能去哪裡是最大問題；她關注醫療照顧重症兒已超過二十年。"}, {"t": 15938, "kind": "挑戰", "tags": ["重症兒童"], "text": "醫療照顧重症兒是「兒童」與「身心障礙者」的交集，還要依賴許多管路與儀器；照顧得好就能順利長大，有孩子小時候氣切，長大後完全看不出來。"}, {"t": 15994, "kind": "建議", "tags": ["重症兒童"], "text": "台灣目前對重症兒沒有統一定義，協會自行提出建議：18歲以下、日常生活中需使用醫療照顧、管路、儀器或維生設備者，例如居家氧氣、氣切、呼吸器、抽痰、胃管、造口、洗腎、中央靜脈營養、導尿管等。"}, {"t": 16060, "kind": "數據", "tags": ["重症兒童", "住宿式機構"], "text": "全台兒童慢性呼吸照護病房只有約5家，零星分布，其餘重症兒多與成人、長者混住；約20年前孩子若送進養護或護理機構，常在兩年內死亡，現在已進步很多。"}, {"t": 16148, "kind": "挑戰", "tags": ["家庭照顧者", "重症兒童"], "text": "家長帶孩子回家要學抽痰、氣切照護、氧氣與呼吸器、胃造口、鼻胃管等，家中常有五六台機器，每台都要會設定、清潔與保養。"}, {"t": 16342, "kind": "挑戰", "tags": ["家庭照顧者"], "text": "有媽媽說聽到機器警示聲就會跳起來，長期睡不好；醫護人員一天上班8到12小時，居家照顧者卻是24小時不停，連找替手喘息都很困難。"}, {"t": 16452, "kind": "挑戰", "tags": ["跨部會協作", "重症兒童"], "text": "居家醫療、早期療育、身障福利、長期照顧、特殊教育五套制度各自發展，常被切成衛福部、教育部、長照的事，孩子的生活被切得支離破碎。"}, {"t": 16533, "kind": "挑戰", "tags": ["長照3.0", "人力培育"], "text": "家長反映長照語言治療師因孩子有氣切就說不會做；服務又限區域、不能跨區，名義上有資源實際上用不到。"}, {"t": 16559, "kind": "政策", "tags": ["健保給付", "居家醫療", "重症兒童"], "text": "健保居家呼吸照護限使用呼吸器者，僅氣切的孩子不符資格；2016年起有居家醫療整合計畫，2021年起新生兒科、兒童胸腔科、兒童重症科醫師也可居家訪視呼吸器依賴兒童。"}, {"t": 16612, "kind": "政策", "tags": ["健保給付", "居家醫療", "重症兒童"], "text": "健保自2026年4月1日起實施兒童居家訪視加成：未滿6個月加成60%、6個月至未滿2歲30%、2歲至未滿7歲20%（依講義）；呂理事長對此表示感謝。"}, {"t": 16639, "kind": "建議", "tags": ["居家醫療", "重症兒童"], "text": "真正需要居家醫療的不只呼吸器兒童，鼻胃管、臥床腦性麻痺兒等也需要，但目前缺乏整合照顧；應從需求出發擴大收案，居家整合計畫理論上不分對象，可再擴大。"}, {"t": 16726, "kind": "政策", "tags": ["重症兒童", "居家醫療"], "text": "國健署「低（含極低）出生體重兒居家照護計畫」已有81家合作醫院、累計近6,000人收案，並納入攜帶管路或儀器的早產兒；但計畫只追蹤到約2歲，之後中斷，制度銜接出現缺口。"}, {"t": 16880, "kind": "挑戰", "tags": ["長照3.0", "重症兒童"], "text": "長照失能分8級，她認為重症兒九級、十級都不夠；但官方曾說長照額度大家用不到一半，她反問是不是服務本身不好用，例如不能陪同上學、就醫等限制。"}, {"t": 16965, "kind": "挑戰", "tags": ["重症兒童", "人力培育"], "text": "約20年前帶氧氣、呼吸器的孩子照樣能做早療，近年許多發展中心反而因害怕氧氣、呼吸器而拒收，她認為是倒退；也曾有治療師讓孩子血氧掉到60還要他繼續用力，顯示專業訓練必要。"}, {"t": 17066, "kind": "挑戰", "tags": ["就學與教育", "重症兒童"], "text": "曾有縣市鑑輔會認為重症兒在家教育、每週一兩小時巡迴輔導就好；也有縣市主動問有什麼困難，派車、找專業人員一起解決，後者才是特教應有的做法。"}, {"t": 17150, "kind": "挑戰", "tags": ["就學與教育"], "text": "特殊教育法的13類障礙中，醫療重症兒只能歸在「其他」；有孩子能出國旅行，卻進不了隔壁學校。學校也有壓力，必須給資源，不能硬塞給學校。"}, {"t": 17213, "kind": "建議", "tags": ["就學與教育", "重症兒童"], "text": "特教法雖規定不得因身障拒絕入學並應提供必要支持，實務上卻設下各種門檻；應在IEP中加入個別健康照顧與生活照顧計畫，並講清楚緊急應變處置與各方職責。"}, {"t": 17294, "kind": "策略", "tags": ["重症兒童"], "text": "強調「生病之外還有生活」，帶孩子外出旅行、參與活動，並推廣「我的優勢卡」，看見孩子的價值與優勢，而非只看到負擔。"}, {"t": 17432, "kind": "策略", "tags": ["重症兒童", "跨部會協作"], "text": "台灣重症兒360發展協會由專業人員組成，2025年3月成立，結合各家長與病友團體共同發聲，並承接政府相關計畫。"}, {"t": 17487, "kind": "挑戰", "tags": ["重症兒童", "人力培育"], "text": "依衛福部函釋，「抽吸」是淺抽到口腔或人工氣道前段，「抽痰」才能深抽；痰卡住時目前法律上只有家人或醫事人員能處理，等於需要24小時護理師在旁，立委也曾質詢此事。"}, {"t": 17550, "kind": "建議", "tags": ["重症兒童", "人力培育"], "text": "協會多次建議政府定義醫療照顧與生活照顧範圍未果，今年3月自行提出版本送衛福部，至今無回音；建議衛福部整合司署共識，區分醫事人員、受訓非醫事人員、一般人可做的事。"}, {"t": 17731, "kind": "策略", "tags": ["人力培育", "長照3.0"], "text": "協會承接長照司「失能重症兒童照顧服務員特殊訓練計畫」，培訓照服員、師資及照管與A個管，並出版公版講義與照顧服務手冊；講義列明課程為16小時研習加8小時實習、評核70分及格。"}, {"t": 17783, "kind": "建議", "tags": ["人力培育"], "text": "她認為只准家人或醫事人員抽痰並不可行，護理人力本就不足；應開放經訓練、認證並有督導的照顧人員執行。"}, {"t": 17915, "kind": "策略", "tags": ["就學與教育", "人力培育"], "text": "在國教署委託下，與陽明交大羅鴻基物理治療師等推動「特殊醫療照顧兒童就學照顧訓練課程」，含教育行政、照顧知能、照顧技能、師資培訓與數位課程五類，預計2027年2月完成。"}, {"t": 17977, "kind": "策略", "tags": ["日本經驗", "重症兒童"], "text": "2025年底辦理台日交流，邀日本前田浩利醫師來台並拜會立法院；日本也正面對重症兒滿18歲後的自立生活問題。"}, {"t": 18090, "kind": "建議", "tags": ["重症兒童", "跨部會協作"], "text": "建議設專責單位，並建立「重症兒專責諮詢個案管理中心」單一窗口，從出院準備就開始協調；家長說「不要再讓家長自己玩制度闖關遊戲」。"}, {"t": 18175, "kind": "建議", "tags": ["重症兒童"], "text": "要訂出重症兒定義並建立統計，才知道孩子在哪裡、如何提供資源；目前有錢家庭的孩子照顧很好，弱勢家庭什麼都沒有，落差很大。"}, {"t": 18255, "kind": "政策", "tags": ["重症兒童", "跨部會協作"], "text": "社家署今年6月召開失能重症兒童專家學者諮詢會議，討論定義、資源盤點、制度銜接等，但結論尚未公布落實；她感謝社家署並建議委託研究計畫盤點需求與資源。"}, {"t": 18288, "kind": "建議", "tags": ["日本經驗", "重症兒童"], "text": "希望參考日本《醫療照顧需求兒童及家庭支援法》，為重症兒建立法制與跨部會支持體系。"}, {"t": 18313, "kind": "政策", "tags": ["重症兒童", "跨部會協作"], "text": "立法院今年8月會議已要求衛福部邀集相關部會，6個月內提出重症兒整合照顧規劃報告，預計2027年春節前後提出。"}]}, {"id": "4-2", "slot": "13:00–15:30", "title": "他山之石：日本障礙兒照顧與居家醫療的發展", "role": "與談", "speaker": "楊千慧 醫師", "org": "育睿診所", "orgType": "基層診所", "handout": "https://drive.google.com/file/d/1hAqNB7rhMCYoPxnOrhvzssdk4T0uLMSM/view", "t": 18393, "summary": "楊千慧醫師介紹日本重症身心障礙兒者與醫療照顧兒制度及小兒在宅醫療發展。她指出日本的改變是一次次社會事件累積而來：從機構化照顧、照顧悲劇，到醫療進步後出現「制度縫隙中的孩子」，再因墨東醫院事件推動NICU出院支援與小兒在宅醫療據點。跨黨派「永田町兒童未來會議」促成2021年《醫療照顧兒支援法》，明定各地設支援中心與就學支援，2026年再修法處理「18歲之壁」。她也說明日本的人數統計方式、判定分數綁定福利給付與排痰抽吸的法制化。", "points": [{"t": 18533, "kind": "策略", "tags": ["日本經驗", "居家醫療"], "text": "日本青空會前田浩利醫師是小兒科醫師，提倡0到100歲的在宅醫療；起因是重症兒家長在路上看到訪視車，主動請他看孩子，才展開小兒在宅醫療。"}, {"t": 18664, "kind": "挑戰", "tags": ["日本經驗", "家庭照顧者"], "text": "日本從1970年代起陸續發生家長因壓力過大殺害障礙子女的悲劇，促使社會思考加強社區支援；醫療進步後出現有醫療需求的障礙兒，在社區或機構都難以安置，被稱為「制度縫隙中的孩子」。"}, {"t": 18852, "kind": "策略", "tags": ["日本經驗", "住宿式機構"], "text": "1958年家長與醫師成立島田療育園，後來發展為各地的療育中心；當時以廣設重症心身障礙兒機構為主要訴求。"}, {"t": 18969, "kind": "挑戰", "tags": ["日本經驗", "人力培育"], "text": "1970年代機構人力不足、職業傷害等問題引發罷工，日本將重症心身障礙機構照顧比定為1比1，但實際常找不到足夠人力；1978年開始緊急一時保護制度，是喘息服務的前身。"}, {"t": 19064, "kind": "政策", "tags": ["日本經驗"], "text": "1996年發表「超重症兒」分數判定，在大島分類上加入呼吸器、鼻胃管、氧氣等醫療需求分數，並與障礙福利給付連結。"}, {"t": 19200, "kind": "挑戰", "tags": ["日本經驗", "居家醫療"], "text": "2008年墨東醫院事件：急產孕婦遭7家醫院以NICU滿床拒收後死亡；調查發現許多穩定但依賴呼吸器的嬰兒因家長不會照顧而長住NICU，引發讓孩子回社區照顧的政策反思。"}, {"t": 19324, "kind": "政策", "tags": ["日本經驗", "居家醫療", "出院準備"], "text": "此後東京都推動NICU出院支援模範事業，勇美財團成立小兒在宅醫療推進會；厚生勞動省105個在宅醫療連攜據點中有3個為小兒據點，2013年擴大到8個縣市。"}, {"t": 19386, "kind": "政策", "tags": ["日本經驗", "人力培育"], "text": "2012年日本修正社會福祉士及介護福祉士法，讓照服員執行排痰抽吸與管灌有法源依據。"}, {"t": 19422, "kind": "挑戰", "tags": ["就學與教育", "日本經驗"], "text": "醫療照顧兒增加後出現上學問題，學校不會抽痰、照顧鼻胃管，就要求家長陪讀，「家長陪同問題」急增。"}, {"t": 19454, "kind": "策略", "tags": ["日本經驗", "跨部會協作"], "text": "2015年成立跨黨派「永田町兒童未來會議」，核心人物包括孩子為重症兒的野田聖子議員、戶枝陽一理事長與前田醫師，定期彙整各地問題與現有制度。"}, {"t": 19519, "kind": "政策", "tags": ["日本經驗"], "text": "2016年修正障礙者總合支援法與兒童福祉法，首次在法律中定義「醫療照顧兒」，但政府只有「努力的義務」，約束力不足。"}, {"t": 19548, "kind": "挑戰", "tags": ["就學與教育", "日本經驗"], "text": "2020年川崎判決：一名使用呼吸器、沒有智能障礙的男童想讀一般小學，被要求就讀特教學校，提告敗訴；後來搬到東京世田谷區才順利入學，顯示各地落差很大。"}, {"t": 19672, "kind": "政策", "tags": ["日本經驗", "重症兒童"], "text": "2021年6月日本國會全體一致通過跨黨派起草的《醫療照顧兒支援法》，政府負實際責任；2022年健保診療報酬也配合多項修訂。"}, {"t": 19706, "kind": "政策", "tags": ["日本經驗", "重症兒童", "就學與教育"], "text": "支援法兩大重點：各地都要設「醫療照顧兒支援中心」作為單一諮詢窗口，並明定就學支援，讓父母能去上班。"}, {"t": 19742, "kind": "政策", "tags": ["日本經驗", "重症兒童"], "text": "為解決滿18歲服務中斷的「18歲之壁」，2026年7月修法為「醫療照顧兒等支援法」，讓制度延伸到成年後。"}, {"t": 19742, "kind": "數據", "tags": ["日本經驗", "重症兒童"], "text": "日本醫療照顧兒約從2010年的1萬人增加到2025年的2萬人；若納入成年者，推估約7萬人。"}, {"t": 19784, "kind": "政策", "tags": ["日本經驗", "重症兒童"], "text": "支援法定義的醫療照顧包括以人工呼吸器進行呼吸管理、排痰抽吸及其他醫療行為；醫療照顧兒指為維持日常與社會生活需持續接受醫療照顧的兒童。"}, {"t": 19815, "kind": "策略", "tags": ["日本經驗", "重症兒童"], "text": "人數統計原本只能從文部科學省掌握特教學校學生，最後改用健保申報資料，例如在宅抽痰、在宅呼吸器指導管理費的申請件數來推估，值得台灣參考。"}, {"t": 19876, "kind": "數據", "tags": ["日本經驗", "重症兒童"], "text": "超重症兒分數例如：呼吸器10分、氣切8分、每小時抽吸1次以上8分、每天6次以上3分，總分25分以上為超重症兒（講義另載10分以上為準超重症兒）。"}, {"t": 19935, "kind": "策略", "tags": ["日本經驗", "重症兒童"], "text": "智力正常、能跑能說但需呼吸器或鼻胃管的孩子不符合重症兒定義，因此另訂「醫療照顧兒判定分數」，並加入「意外防護」加分，反映活動力高的孩子需要更多人力；此部分需由醫師判定。"}, {"t": 19991, "kind": "政策", "tags": ["日本經驗", "財源與預算"], "text": "判定分數綁定福利給付，例如課後日照依分數決定人力比與給付，醫療分數高者可到1比1，只要有一項醫療照顧就可列為醫療照顧兒。"}, {"t": 20057, "kind": "政策", "tags": ["日本經驗", "人力培育"], "text": "日本早期也是靠行政通知處理排痰抽吸，因問題太大才正式立法；研修分三類：第一、二號主要針對機構，受訓後可服務多人；第三號是針對特定個案，在個案家中由護理師或醫師確認後，只能為該個案抽吸。"}, {"t": 20147, "kind": "策略", "tags": ["出院準備", "日本經驗"], "text": "日本重症兒出院前會召開出院準備會議，重症個案可能同時由2到3家居護所與照服單位共同服務；醫療照顧兒支援中心雖只是小辦公室，卻以人為本做很多協調。"}, {"t": 20209, "kind": "策略", "tags": ["居家醫療", "日本經驗"], "text": "出院當天居家醫師、居護所護理師與呼吸器、氧氣廠商會一起到家銜接；需要氧氣時約1小時內可送到家，醫師在家也能做腹膜透析、中心靜脈營養等處置。"}, {"t": 20243, "kind": "策略", "tags": ["居家醫療", "日本經驗"], "text": "日本居家護理可一週訪視約三次，並有詳細的重症兒沐浴流程；治療師可做居家復健甚至兒童安寧，藥局也提供在宅送藥，台灣健保目前仍無兒童居家復健。"}]}, {"id": "4-3", "slot": "13:00–15:30", "title": "重症兒就學照顧", "role": "與談", "speaker": "楊玲玲 秘書長", "org": "台灣重症兒360發展協會", "orgType": "社福團體", "handout": "https://drive.google.com/file/d/1Uaphp4jwIU44SxD28Y3pESLaWOSK4YL1/view", "t": 20436, "summary": "楊玲玲秘書長分享協會2026年8月赴日參訪15個單位的見聞，聚焦醫療照顧兒的就學照顧與支援中心。她比較筑波特別支援學校、東京都立鹿本學園、港區台場學園的護理人力、接送、陪讀與緊急應變，說明日本以主治醫師指示書為核心，搭配學校指導醫與經1號至3號研修的教師執行抽痰管灌；並介紹宮城縣CHILFA與東京都立兒童醫療中心兩種支援中心，以協調員作為跨專業單一窗口。她指出台灣在服務模式、資源串聯與政策一致性上仍有缺口，期待可依靠的重症兒照顧政策。", "points": [{"t": 20477, "kind": "策略", "tags": ["重症兒童", "就學與教育", "日本經驗"], "text": "協會二十多年來以家訪照顧重症兒家庭，但發現孩子成長需要上學，居家與學校的照顧需求不同，因此今、去年的日本參訪首次從小兒在宅醫療延伸走進學校。"}, {"t": 20556, "kind": "策略", "tags": ["日本經驗", "重症兒童"], "text": "2026年8月17–27日共10天參訪15個單位，涵蓋喘息、日照、小規模多機能等社區服務；今年特別看到由護理師、治療師等非醫師醫事人員開業的日照與照顧機構，且不只在都會區，偏遠地區也有。"}, {"t": 20714, "kind": "策略", "tags": ["日本經驗", "住宿式機構"], "text": "筑波一位自身養育障礙兒的護理師負責人，除自設日照，也協助物理、職能治療師成立重症兒日間照顧單位；茨城縣看護協會則協助成立由醫事人員開業的「護理小規機」。"}, {"t": 20900, "kind": "數據", "tags": ["就學與教育", "日本經驗", "重症兒童"], "text": "筑波特別支援學校全校約430名學生，有醫療照顧需求者35位，配置養護教師及17位專任或兼任護理師執行醫療照顧，指導醫每1–2個月到校一次。"}, {"t": 20964, "kind": "挑戰", "tags": ["就學與教育", "日本經驗"], "text": "筑波特支校交通外包、無護理師隨車，需抽吸的孩子由家長接送；入學前提供3次、每次半天且含共餐的學前體驗。"}, {"t": 21041, "kind": "數據", "tags": ["就學與教育", "日本經驗", "人力培育"], "text": "東京都立鹿本學園有醫療照顧兒50位、其中約25位需管灌；配置養護教師3位、專職護理師7位、兼職5位、督導1位，另與派遣單位簽約派遣護理師10位，學期需求多時可機動增派；常態有15位教師具1、2、3號研修資格之一。"}, {"t": 21107, "kind": "策略", "tags": ["就學與教育", "日本經驗"], "text": "鹿本學園向政府申請特殊醫療接送車輛，家屬不需負擔費用並安排隨車護理師；入學前1–2年起每月可安排一次適應，氣切加呼吸器的孩子開學後陪讀最多約20多天，家長就退場。"}, {"t": 21136, "kind": "策略", "tags": ["就學與教育", "日本經驗"], "text": "鹿本學園校長強調學校是讓孩子成長與學習的場域，而非醫療照顧場域，目標是減少家長陪讀；「在家教育」須由家長自行提出意願，不由學校主導。"}, {"t": 21205, "kind": "策略", "tags": ["就學與教育", "日本經驗"], "text": "港區台場學園為一般中小一貫學校，港區有11位醫療照顧兒、該校2位；有重症兒才簽約派遣護理師，入學前須向主治醫師取得每年更新的醫師指示書，陪讀多在入學後1–2天退場。"}, {"t": 21354, "kind": "策略", "tags": ["就學與教育", "日本經驗"], "text": "筑波特支校的緊急應變計畫依主治醫師指示書、家長平日照顧方式與學校作息個別訂定，由學校護理師擬定、家長同意後才執行；教師負責觀察、準備與聯絡，護理師不一定在旁，啟動者可能就是班級老師。"}, {"t": 21488, "kind": "策略", "tags": ["就學與教育", "日本經驗"], "text": "日本醫師指示書除基本資料外，主要說明呼吸照顧（氣切、抽吸頻率、呼吸器、氧氣）與腸胃營養（餵食方式、時間、份量、鼻胃管或胃造廔），以及癲癇等緊急處置與給藥。"}, {"t": 21632, "kind": "策略", "tags": ["就學與教育", "重症兒童"], "text": "學校把指示書中的緊急應變措施直接寫進孩子每日作息表，並設執行者簽名欄，事情發生時不必再翻檔案找處置方式，是台灣學校可直接仿效的做法。"}, {"t": 21705, "kind": "策略", "tags": ["就學與教育", "日本經驗"], "text": "鹿本學園緊急處置標準：SpO2低於95%持續5分鐘即送醫，持續低於90%超過5分鐘或呼吸不穩定則緊急送醫；胃造廔管脫落由家長帶往醫院；發燒先排除姿勢或環境因素，確認發燒才請家長帶回。"}, {"t": 21802, "kind": "策略", "tags": ["就學與教育", "日本經驗"], "text": "鹿本學園所有學生藥品統一存放保健室，一般口服藥可由教師協助；醫療照顧兒給藥由護理師或受訓教師執行，有醫師指示書時教師可給塞劑。日本文部科學省指引：癲癇需緊急塞劑給藥時只須告知家長、不必先取得同意，聯絡不到家長則由校長全權處理。"}, {"t": 22038, "kind": "策略", "tags": ["人力培育", "日本經驗", "就學與教育"], "text": "日本照顧人員抽痰管灌研修分三級：1號可執行抽痰與管灌，能力近似護理師；2號只能執行其中一項；3號僅限針對特定學生的特定照顧項目，須在該孩子身上演練考核通過。"}, {"t": 22103, "kind": "策略", "tags": ["人力培育", "日本經驗"], "text": "厚生勞動省官網公開喀痰吸引研修制度：辦訓單位申請時須填明口腔、鼻腔、氣切抽吸或鼻胃管、胃造廔管灌等訓練項目，完訓者資料也公開可查，方便各地找人力。日本法律原規定抽痰管灌屬醫療行為，但在本人書面同意、適當醫學管理等條件下允許照服員等執行。"}, {"t": 22173, "kind": "策略", "tags": ["就學與教育", "日本經驗"], "text": "台場學園位於海埔新生地、海拔僅約5.7公尺，校內無電梯，防災演練以垂直避難為主，包括如何把三樓坐輪椅的醫療照顧兒移到一樓，由副校長統籌。"}, {"t": 22239, "kind": "策略", "tags": ["重症兒童", "日本經驗"], "text": "日本設支援中心的理念：重症兒的生活與照顧需求遠大於醫療需求，出院後在家時間遠多於住院；目標是減輕家屬負荷、由專業人員提供照護指示與支持、關注容易被忽略的手足，穩定整個家庭。"}, {"t": 22310, "kind": "策略", "tags": ["重症兒童", "日本經驗", "跨部會協作"], "text": "支援中心的核心角色是「醫療照顧兒協調員」，作為跨專業樞紐連結醫師、護理師、治療師、照顧服務、公部門與學校；從出院準備階段就介入，盤點住家附近可用服務與轉銜、統計需求量，並召開個案討論的聯繫會議處理困難轉銜。"}, {"t": 22376, "kind": "數據", "tags": ["重症兒童", "日本經驗"], "text": "宮城縣仙台的CHILFA支援中心由從業人員協會承辦，2022年起受縣府委託；服務醫療照護兒／者共約886人（未滿18歲423人、18歲以上463人），2022–2025年諮詢量1,239件、成長約45.9%。"}, {"t": 22448, "kind": "策略", "tags": ["人力培育", "日本經驗"], "text": "CHILFA有約聘醫師1位、專任職員3名（護理師、物理治療師、社工），皆須具備上課認證的相談支援協調員資格；並與公部門合辦培訓，每年5次線上課程，講義列學員總數392位。"}, {"t": 22489, "kind": "數據", "tags": ["重症兒童", "日本經驗", "財源與預算"], "text": "東京都立兒童醫療中心的支援中心設於醫院內但為獨立組織，人員皆兼職；指導醫每2個月到校一次、每次2–3位醫師看4–5位孩子約2.5小時；講義列每年撥款1,450萬日圓、中央與地方各半。"}, {"t": 22630, "kind": "策略", "tags": ["就學與教育", "日本經驗", "人力培育"], "text": "東京都立醫院醫師擔任學校指導醫：到校培訓非醫事人員的醫療照護並考核、實地觀察老師執行技術，確認在校照顧安全，並協調主治醫師指示與學校實際可行之間的落差。"}, {"t": 22707, "kind": "策略", "tags": ["就學與教育", "日本經驗"], "text": "指導醫最常被問的兩題：抽吸壓力（主治醫師會在指示書寫明；講義列校護上限30–40 kPa、非醫事人員20 kPa，講者指出仍高於台灣的上限），以及在校氣切管滑脫，護理師在場可重新置回，受過訓練的特教老師也可協助，校內有模具可練習。"}, {"t": 22745, "kind": "挑戰", "tags": ["重症兒童", "跨部會協作"], "text": "對照台灣現況：「點」上重症兒照顧、喘息、日照、機構等服務模式不足；「線」上從住院到回家，醫療、照顧與生活資源難以串聯，家長不知去哪裡找資訊；「面」上中央與地方、都會與偏遠缺乏一致性政策。"}]}, {"id": "4-4", "slot": "13:00–15:30", "title": "童羽之家分享", "role": "與談", "speaker": "黃啟南 主任", "org": "臺北市立聯合醫院和平婦幼院區兒童保健科", "orgType": "醫院", "handout": "https://drive.google.com/file/d/1BKahNajqvMPT5hZpa_aShSPbjTd2KF3i/view", "t": 22864, "summary": "黃啟南主任介紹臺北市立聯合醫院婦幼院區的「童羽之家」，一家專為兒童設計的住宿式長照機構。他指出重症兒缺乏法定定義與統計，從急重症到返家之間沒有專責照護場域，健保PAC六類也沒有兒童類別。童羽之家以中繼轉銜為核心，提供特殊需求兒安置、喘息與兒童急性後期照護，一年半累計收住19位孩子，功能獨立程度初步提升；但佔床率約五成，卡在宣傳不足、需身障證明與自付費用沉重。他提出三項建議：判定工具與單一窗口、試辦兒童PAC、兒童PAC納入健保。", "points": [{"t": 22930, "kind": "挑戰", "tags": ["重症兒童"], "text": "醫療照護重症兒目前在台灣沒有明確名詞與法定定義，大致指未滿18歲、重度至極重度身心障礙、日常生活需特殊醫療照護（氧氣、氣切、呼吸器、抽痰、管灌等）的孩子；長照需求評估多落在第7、8級。"}, {"t": 23034, "kind": "數據", "tags": ["重症兒童"], "text": "最接近的官方統計是身心障礙兒少：全國18歲以下約5.6萬人（講義列113年底56,223人，臺北市5,889人、新北市10,710人），但與重症兒僅部分重疊、並不相等。"}, {"t": 23086, "kind": "挑戰", "tags": ["重症兒童", "出院準備"], "text": "重症兒從急重症期到返家之間，有呼吸器者可下轉RCW（聯醫陽明院區有兒童RCW），但沒有呼吸器而有其他醫療照護需求的孩子，現行體系沒有可銜接的地方，形成「復原中程」的照護真空。"}, {"t": 23137, "kind": "挑戰", "tags": ["急性後期照護", "重症兒童", "健保給付"], "text": "健保急性後期整合照護計畫（PAC）六類適應症（腦中風、燒燙傷、創傷性神經損傷、脆弱性骨折、心臟衰竭、衰弱高齡）都以成人為主，複雜早產兒、先天性心臟病或呼吸道術後、神經肌肉疾病急性感染後等兒童情境都未涵蓋；長照住宿也不在健保範圍。"}, {"t": 23216, "kind": "挑戰", "tags": ["重症兒童", "住宿式機構"], "text": "脆弱家庭的孩子需要安置時，一般寄養家庭與安置機構無法照顧有氣切、多管路的孩子，只能暫住成人護理之家或身障機構；講義列112年有176名特殊需求兒少安置於成人機構，至114年底仍有90人。"}, {"t": 23296, "kind": "挑戰", "tags": ["重症兒童", "長照3.0", "健保給付"], "text": "長照給付依失能程度，到一定程度就達天花板，有無呼吸器、照護多複雜都無法再多支應；健保可支應門診與居家醫療，但慢性住宿只有RCW符合，失能高、無呼吸器的孩子找不到保母、幼兒園或照顧者，全靠家長全年無休照顧。"}, {"t": 23397, "kind": "策略", "tags": ["住宿式機構", "重症兒童"], "text": "童羽之家構想始於2019年（講義：108年6月首次向衛生局提案），經多次轉折，2025年完工並試營運，今年婦幼專責院區揭牌時同步公布，預計年底開滿整層29床。"}, {"t": 23481, "kind": "策略", "tags": ["住宿式機構", "急性後期照護", "重症兒童"], "text": "經專家指導後定位調整為「中繼轉銜」：除一般兒童長照外，收住三類對象——社政轉介的特殊需求兒安置、重症兒家庭的喘息服務，以及兒童急性後期照護（最長12週積極復能並訓練家長），目標是讓孩子返家、去機構化。"}, {"t": 23534, "kind": "數據", "tags": ["住宿式機構", "重症兒童"], "text": "童羽之家設於婦幼院區七樓，29床（另1隔離床），有單人、雙人、三人房，以雙人房為主；講義列月費單人房6萬元、雙人房4.9萬元、三人房4.5萬元，空間以溫暖童趣設計，不像醫院。"}, {"t": 23559, "kind": "數據", "tags": ["重症兒童", "住宿式機構"], "text": "營運一年半累計收住19位孩子，年齡約1個月至7歲，背景包括早產、複雜性先天性心臟病、受虐性腦傷、兒虐、疏忽合併發展遲緩與脆弱家庭等。"}, {"t": 23588, "kind": "數據", "tags": ["重症兒童", "急性後期照護"], "text": "服務類型以安置／緊急安置為大宗（講義列12位），兒童急性後期照護5位（其中4位靠社會局經費補助），喘息服務2位由家長直接聯繫。"}, {"t": 23615, "kind": "策略", "tags": ["重症兒童", "跨部會協作"], "text": "緊急安置流程：社會局、家防中心、社工或司法兒少保護系統轉介，確認沒有其他安置機構能接手後入住；跨專業團隊提供生活照顧、醫療與發展復能並定期個案討論，再依社政評估轉銜寄養家庭、安置機構或返家。"}, {"t": 23668, "kind": "策略", "tags": ["重症兒童", "急性後期照護"], "text": "標竿個案：脆弱家庭的複雜先天性心臟病嬰兒，出生後一直住在醫學中心、依賴鼻胃管且發展落後，一般機構無法接手；轉入後以進食訓練為重點，6週移除鼻胃管、體重增加、發展逐漸追上，順利下轉社區。"}, {"t": 23743, "kind": "數據", "tags": ["重症兒童", "急性後期照護"], "text": "以兒童版功能獨立量表（WeeFIM）與同齡比較，5位較長期個案入住時平均功能獨立程度為同齡的43.8%，3–6個月後提升到65.4%；講者強調個案數少，屬初步成果。"}, {"t": 23818, "kind": "策略", "tags": ["家庭照顧者", "重症兒童"], "text": "孩子要訓練，家長也要訓練：對學習較慢的家長反覆示範、用簡單圖卡、手把手練習並考核，內容包括拍痰抽痰、管灌、管路照護與居家呼吸器等設備申請，並把經驗整理成照顧者訓練SOP。"}, {"t": 23874, "kind": "挑戰", "tags": ["住宿式機構", "重症兒童"], "text": "目前開放18床、平均佔床率約五成，未如預期一開床就住滿。原因之一是宣傳不足，許多家庭不知道兒童也能申請長照身分與喘息，將持續向醫學中心、社會局、家防中心與家長團體宣傳。"}, {"t": 23931, "kind": "挑戰", "tags": ["長照3.0", "重症兒童"], "text": "兒童取得長照身分多須先有身障證明，但兒科醫師常不願太早開永久證明；經請教中央與兒科前輩，可先開暫時性身障證明即可取得長照身分，正持續向兒科醫師宣導。"}, {"t": 23982, "kind": "挑戰", "tags": ["重症兒童", "家庭照顧者", "財源與預算"], "text": "自付費用沉重是最大問題：月費多在4.5萬至4.9萬元，長者覺得在臺北市中心算便宜，但對年輕家長仍難負擔，比現有護理之家貴上許多。"}, {"t": 24057, "kind": "挑戰", "tags": ["家庭照顧者", "重症兒童"], "text": "孩子的健康與照護問題往往是整個家庭問題的反射；機構能照顧好孩子，卻難照顧好受傷的家庭。曾有受虐兒入住時不會說話，一個月後就能說出整句話，顯示原生家庭的疏忽讓潛力未被發揮。"}, {"t": 24136, "kind": "策略", "tags": ["重症兒童"], "text": "意外發現同儕的力量：功能較好的孩子會照顧較小的孩子，彼此模仿陪伴，語言與活動能力都提升。"}, {"t": 24162, "kind": "策略", "tags": ["日本經驗", "重症兒童"], "text": "日本《醫療照護兒及其家庭支援法》訂有明確定義與醫師判定量表（如人工呼吸器10分、氣切8分），新案得1分以上即認定，不論年齡、出院即可使用福利制度，並可據以精算人數與經費。"}, {"t": 24244, "kind": "建議", "tags": ["重症兒童", "跨部會協作"], "text": "建議一：建立一致的定義、判定工具與單一窗口。目前一個家庭要分別找醫院、長照管理中心（喘息每年最多約21天）、教育局與學校（特教鑑定）、社政（身障補助），家長被迫自己當協調員；有定義才能精算人數與預算。"}, {"t": 24372, "kind": "政策", "tags": ["急性後期照護", "重症兒童"], "text": "建議二：試辦兒童PAC。童羽之家已在去年底（講義：114年12月1日）向衛福部醫事司提出兒童PAC試辦計畫，審查中，因今年總預算延後尚未啟動；原規劃兩年、預估收案60至105人次，建立收案條件、成效指標與成本計算。"}, {"t": 24399, "kind": "建議", "tags": ["急性後期照護", "健保給付", "重症兒童"], "text": "建議三：兒童PAC試辦成功後納入健保給付，在急性後期整合照護計畫增設兒童類別，讓模式能推廣到其他醫院。"}, {"t": 24425, "kind": "建議", "tags": ["急性後期照護", "人力培育", "重症兒童"], "text": "少子化使中型醫院小兒科住院量下降、經營困難、留不住醫師，可利用空出的小兒科病房與人力轉型承接兒童PAC，補起照護缺口。"}]}, {"id": "4-5", "slot": "15:40–16:30", "title": "綜合座談：立法委員、衛福部、教育部與談", "role": "座談", "speaker": "王正旭委員／石崇良部長／孫敏儀組長", "org": "立法院、衛生福利部、教育部國教署", "orgType": "立法院", "host": "陳節如理事長", "t": 25072, "summary": "閉幕綜合座談由陳節如理事長主持，實際與談人為立法委員王正旭、衛福部石崇良部長、教育部國教署孫敏儀組長。孫組長說明特教學校護理與助理人力、維生裝置補助及就學照顧訓練。石部長提出五個方向：年底前完成重症兒需求盤點、明年啟動兒童PAC試辦、試辦醫院型與社區型資源中心、由公立醫院示範兒童專屬住宿機構、讓居家醫療與長照服務延伸進校園，並表示優先解決抽痰人力。家長團體與智障者家長總會則提出抽痰無人可做、離校後支持中斷、18歲轉銜與法規全面檢視等訴求。", "points": [{"t": 25199, "kind": "政策", "tags": ["就學與教育", "重症兒童", "人力培育"], "text": "國教署孫敏儀組長：特教學校除編制內護理師，去年底起部分特教學校增加編制外護理師，並配置特教助理人員；部分學校有駐校醫師、治療師或專業團隊入校協助。去年起並補助普通學校為就讀的重症學生購置所需維生裝置等照護資源。"}, {"t": 25295, "kind": "政策", "tags": ["就學與教育", "人力培育", "跨部會協作"], "text": "孫組長：與專業協會合作開辦「特殊醫療照護兒童就學照顧訓練課程」；並與協會、陽明交通大學研議特教學生在校醫療照護與生活照顧行為一覽表，將與衛福部共同研議，作為學校人員的實務參考。"}, {"t": 25514, "kind": "建議", "tags": ["跨部會協作", "日本經驗"], "text": "王正旭委員：日本多以立法引導政策，台灣則多是行政先推政策、需要時再立法補強；希望探討立法與行政如何合作，形成台灣自己的模式。"}, {"t": 26044, "kind": "政策", "tags": ["重症兒童", "數位科技"], "text": "石崇良部長承諾一：先盤點未被滿足的需求。依重症兒360協會建議的條件釐清定義，運用健保與長照資料庫盤出需求缺口，希望年底前完成，作為試辦計畫與服務網布建依據。"}, {"t": 26123, "kind": "政策", "tags": ["急性後期照護", "重症兒童", "健保給付"], "text": "石部長承諾二：明年啟動重症兒／兒童PAC試辦計畫，參考聯醫婦幼院區童羽之家經驗，並請健保署林右鈞組長規劃；因需投入環境硬體與設施，將採公務預算加健保的方式試辦，補上現行PAC六類沒有兒童的缺口。"}, {"t": 26207, "kind": "政策", "tags": ["重症兒童", "跨部會協作"], "text": "石部長承諾三：重症兒照顧橫跨醫療、長照、社福三個領域與不同預算，將同步試辦資源中心，考慮醫院型（可與兒童PAC結合、銜接後續社區資源）與社區型兩種模式，擇點試辦。"}, {"t": 26286, "kind": "政策", "tags": ["住宿式機構", "長照3.0", "重症兒童"], "text": "石部長承諾四：盤點重症兒的長照模式；目前沒有兒童專屬住宿機構、多與成人混住，將研究由公立或部立醫院先行示範兒童專屬住宿式機構，運用長照獎勵計畫，並與兒童PAC結合；喘息方面研究以小規模多機能結合兒童需求試辦。"}, {"t": 26400, "kind": "政策", "tags": ["居家醫療", "就學與教育", "健保給付"], "text": "石部長承諾五：居家醫療（健保居家醫療照護整合計畫）與居家長照多以家為服務地點，但孩子白天在學校；將研究讓這些服務延伸進校園，回應呂立醫師提出到校服務能否給付的問題。"}, {"t": 26481, "kind": "政策", "tags": ["就學與教育", "跨部會協作", "人力培育"], "text": "石部長：將與教育部合作處理校園照顧的特殊需要，可能涉及法規解釋或鬆綁，參考日本由受訓教職員協助執行；五個方向將帶回與醫事司、長照司、社家署、健保署共同討論。"}, {"t": 26556, "kind": "建議", "tags": ["人力培育", "長照3.0"], "text": "陳理事長建議人力鬆綁：專業人員可兼職不必專職，讓「士」級人員協助「師」級；並應規劃照服員能否進入學校與PAC，結合長照與健保兩筆經費；目前學校老師不能抽痰，法規不解套，錢再多也用不上。"}, {"t": 26844, "kind": "挑戰", "tags": ["重症兒童", "人力培育", "家庭照顧者"], "text": "臺北市腦性麻痺及重症兒童家長互助協會王姓家長（孩子17歲）：衛福部函釋雖區分抽痰與抽吸，但機構不清楚而拒絕執行；居服員不能抽、校護引用不得執行侵入性處置的規範拒絕，教室助理員也不能做，家長完全無法喘息，希望培訓人力執行抽痰。"}, {"t": 26960, "kind": "建議", "tags": ["重症兒童", "就學與教育", "社區醫療"], "text": "王姓家長：有氣切、鼻胃管的孩子畢業後支持系統全面中斷，日照一聽鼻胃管就拒收。建議社區醫療與整合照顧計畫明定納入重症兒離校後的照顧安置並就近提供；教育單位積極推動離校轉銜並保留名額；補助或評鑑對收住重症兒的單位加分或加成補助。"}, {"t": 27055, "kind": "政策", "tags": ["就學與教育", "跨部會協作"], "text": "孫組長回應：學生離校前會透過個別化教育計畫（IEP）與家長討論轉銜，並持續與社福、衛福單位研議轉銜過程中教育端可提供的協助。陳理事長另要求國教署正視2歲以上早療責任，孫組長表示將轉請學前教育組參考。"}, {"t": 27161, "kind": "建議", "tags": ["就學與教育", "人力培育", "重症兒童"], "text": "智障者家長總會林惠芳秘書長：教育界不應認為重症孩子只能在家教育；目前僅北、高兩所特殊學校有專案護理師且無給付與人力配置標準，應建立一致的專案護理師制度，並依實際需要補足學生助理員；未來資源中心可由醫師扮演協調學校與主治醫師的角色。"}, {"t": 27296, "kind": "建議", "tags": ["重症兒童", "住宿式機構", "跨部會協作"], "text": "林惠芳秘書長：童羽之家以兒童PAC定位納入健保是最快的路，但也兼負家庭危機安置；兒少安置政策以家庭型態優先，團家、類家已服務重症兒但到18歲銜接不出去，團家試辦20年未正式化，請部長納入社家署一併規劃，並在社區布建計畫中設計對特殊需求者的回應。"}, {"t": 27425, "kind": "建議", "tags": ["跨部會協作"], "text": "林惠芳秘書長請王委員推動全面檢視散落各法的身障與重症兒相關規定，避免見一個問題修一條法、法與法相互衝突。"}, {"t": 27633, "kind": "政策", "tags": ["人力培育", "重症兒童", "跨部會協作"], "text": "石部長回應修法：建議政策先走、試辦後確有需要再修法。以抽痰為例，沒有任何法律規定不能抽痰，是法規解釋問題；在醫療人力吃緊下須讓受過訓練的人執行，將優先解決抽痰人力，並全盤考慮社區銜接、評鑑加分與補助加成等建議。"}, {"t": 27859, "kind": "政策", "tags": ["跨部會協作", "人力培育"], "text": "王正旭委員：贊同全面檢視相關法規，將嘗試用AI協助找出法規衝突；日本2005年以通知、2012年修法開放照顧人員抽痰，台灣可優先處理抽痰與鼻胃管灌由誰執行的爭議。"}, {"t": 28068, "kind": "挑戰", "tags": ["重症兒童", "人力培育", "居家醫療"], "text": "一位居家護理所執行長（旗下有重症嬰幼兒護理團隊）：心臟病、唇顎裂等無侵入性管路的孩子不符重症資源資格，家長只能透過人力公司找「特別護理師」，但這些護理師無處執業登記、缺乏授權與保障，且照顧6歲以下孩子還須符合托育規定。"}, {"t": 28301, "kind": "政策", "tags": ["人力培育", "居家醫療"], "text": "石部長說明癥結在執業登記須依附醫療院所或護理機構，過去曾提議由職業工會辦理執登但護理界反對，仍需溝通；若能執登在居家護理所，就可外包到校園執行抽痰或陪伴。會中請該執行長提出書面意見送衛福部。"}]}]}], "kinds": ["政策", "策略", "數據", "挑戰", "建議"], "tags": ["健康台灣", "長照3.0", "醫照整合", "居家醫療", "在宅急症照護", "急性後期照護", "復健病房", "出院準備", "社區醫療", "住宿式機構", "健保給付", "重症兒童", "就學與教育", "偏鄉", "失智照護", "安寧緩和", "人力培育", "數位科技", "家庭照顧者", "日本經驗", "財源與預算", "跨部會協作"], "orgTypes": ["政府機關", "立法院", "醫院", "基層診所", "社福團體", "專業團體", "主辦單位"]};
